</div>

sources.src/components/Rating.astro:
---
/**
 * Estrellas de solo lectura con relleno fraccionario (4,4 → cuatro llenas y el 40 % de la
 * quinta). Para votar, ver StarRating.astro.
 */
import { formatAverage } from '@/lib/ratings-config';

interface Props {
  rating: number;
  count?: number;
  /** Lado de cada estrella en px. */
  size?: number;
  /** `dark`: sobre fondo ciruela (landings de Ads). */
  tone?: 'light' | 'dark';
  class?: string;
}
const { rating, count, size = 14, tone = 'light', class: className } = Astro.props;
const STAR = 'M12 2.5l2.9 6 6.6.9-4.8 4.6 1.2 6.5L12 17.4 6.1 20.5l1.2-6.5L2.5 9.4l6.6-.9Z';
const GAP = 2;
const width = size * 5 + GAP * 4;
const whole = Math.floor(rating);
const filled = Math.min(width, whole * (size + GAP) + (rating - whole) * size);
---

<span class:list={['inline-flex items-center gap-1.5', className]}>
  <span
    class="relative inline-block shrink-0"
    style={`width:${width}px;height:${size}px`}
    role="img"
    aria-label={`Calificación ${formatAverage(rating)} de 5`}
  >
    {
      [false, true].map((full) => (
        <span
          class="absolute inset-y-0 left-0 flex overflow-hidden"
          style={`gap:${GAP}px;width:${full ? filled.toFixed(1) : width}px`}
          aria-hidden="true"
        >
          {[1, 2, 3, 4, 5].map(() => (
            <svg class="shrink-0" style="max-width:none" width={size} height={size} viewBox="0 0 24 24">
              <path
                d={STAR}
                fill={full ? 'oklch(0.84 0.145 85)' : 'oklch(0.9 0.022 78)'}
                stroke="oklch(0.62 0.12 70)"
                stroke-width="1"
              />
            </svg>
          ))}
        </span>
      ))
    }
  </span>
  <span class="text-sm font-bold">{formatAverage(rating)}</span>
  {/* ciruela-500: AA también sobre crema-100 (ciruela-400 da 4.45:1 ahí). `count > 0` evita pintar un «0». */}
  {
    count != null && count > 0 && (
      <span class:list={['text-xs', tone === 'dark' ? 'text-crema-100/75' : 'text-ciruela-500']}>({count})</span>
    )
  }
</span>

sources.src/components/GeoToast.astro:
---
/**
 * Sugerencia de país no intrusiva. Detecta el país por IP con Cloudflare
 * (/cdn-cgi/trace → loc=XX) y, si falla, por zona horaria. NO usa el idioma del
 * navegador: "es-ES" es habitual en Latinoamérica y proponía España a colombianos
 * (auditoría de diseño 2026-09-22). Persiste la elección en localStorage.
 */
interface Props {
  pathAfterCountry?: string;
  currentCode?: string;
}
const { pathAfterCountry = '/', currentCode = '' } = Astro.props;
---

<div
  id="geo-toast"
  data-path={pathAfterCountry}
  data-current={currentCode}
  class="geo-toast fixed inset-x-0 top-[72px] z-40 hidden border-b border-crema-200 bg-white px-4 py-3 shadow-tarjeta sm:inset-x-auto sm:top-auto sm:right-5 sm:bottom-24 sm:max-w-sm sm:rounded-2xl sm:border sm:p-4 sm:shadow-globo"
  role="status"
>
  <p class="text-sm font-semibold text-ciruela-800">
    Parece que estás en <span id="geo-toast-name"></span>. ¿Ver precios en <span id="geo-toast-cur"></span>?
  </p>
  <div class="mt-3 flex gap-2">
    <a
      id="geo-toast-go"
      href="/"
      class="rounded-full bg-coral-600 px-4 py-2 text-xs font-bold text-white transition-colors hover:bg-coral-700"
    >
      Sí, cambiar
    </a>
    <button
      id="geo-toast-stay"
      class="rounded-full border border-crema-300 px-4 py-2 text-xs font-bold text-ciruela-600 transition-colors hover:bg-crema-100"
    >
      Seguir aquí
    </button>
  </div>
</div>

<script>
  import { trackEvent } from '@/lib/analytics';

  const toast = document.getElementById('geo-toast');
  const NAMES: Record<string, [string, string]> = {
    co: ['Colombia', 'COP'],
    mx: ['México', 'MXN'],
    pe: ['Perú', 'PEN'],
    ec: ['Ecuador', 'USD'],
    cl: ['Chile', 'CLP'],
    ar: ['Argentina', 'ARS'],
    es: ['España', 'EUR'],
    us: ['Estados Unidos', 'USD'],
  };
  const TZ: Array<[RegExp, string]> = [
    [/^America\/Bogota$/, 'co'],
    [/^America\/(Mexico_City|Monterrey|Merida|Cancun|Chihuahua|Hermosillo|Mazatlan|Tijuana|Matamoros|Ojinaga|Bahia_Banderas)$/, 'mx'],
    [/^America\/Lima$/, 'pe'],
    [/^(America\/Guayaquil|Pacific\/Galapagos)$/, 'ec'],
    [/^(America\/Santiago|America\/Punta_Arenas|Pacific\/Easter)$/, 'cl'],
    [/^America\/Argentina\//, 'ar'],
    [/^(Europe\/Madrid|Africa\/Ceuta|Atlantic\/Canary)$/, 'es'],
    [/^America\/(New_York|Chicago|Denver|Los_Angeles|Phoenix|Anchorage|Detroit|Indiana\/.+|Kentucky\/.+|Boise)$|^Pacific\/Honolulu$/, 'us'],
  ];

  async function detectCountry(): Promise<string> {
    try {
      const res = await fetch('/cdn-cgi/trace', { cache: 'no-store' });
      const loc = (await res.text()).match(/^loc=([A-Z]{2})$/m)?.[1]?.toLowerCase() ?? '';
      if (loc) return loc in NAMES ? loc : '';
    } catch {
      /* sin Cloudflare (dev/preview): cae a la zona horaria */
    }
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone ?? '';
    return TZ.find(([re]) => re.test(tz))?.[1] ?? '';
  }

  async function init(el: HTMLElement) {
    const saved = localStorage.getItem('cdgo-country');
    const dismissed = sessionStorage.getItem('cdgo-geo-dismissed');
    if (dismissed) return;
    const current = el.dataset.current ?? '';
    // Quien llega a /{cc}/… desde un buscador ya eligió país en la SERP: no molestar.
    if (current && /google\.|bing\.|duckduckgo\.|yahoo\./.test(document.referrer)) return;
    const detected = saved ? '' : await detectCountry();
    const target = saved && saved !== current ? saved : detected && detected !== current ? detected : '';
    if (!target || !NAMES[target]) return;
    const [name, currency] = NAMES[target];
    document.getElementById('geo-toast-name')!.textContent = name;
    document.getElementById('geo-toast-cur')!.textContent = currency;
    const go = document.getElementById('geo-toast-go') as HTMLAnchorElement | null;
    if (go) {
      go.href = `/${target}${el.dataset.path ?? '/'}`;
      go.addEventListener('click', () => {
        localStorage.setItem('cdgo-country', target);
        trackEvent('select_country', { country_from: current || 'none', country_to: target, source: 'geo_toast' });
      });
    }
    document.getElementById('geo-toast-stay')?.addEventListener('click', () => {
      sessionStorage.setItem('cdgo-geo-dismissed', '1');
      if (current) localStorage.setItem('cdgo-country', current);
      el.classList.add('hidden');
    });
    setTimeout(() => el.classList.remove('hidden'), 2200);
  }

  if (toast) init(toast);
</script>

<style>
  /* Con la barra de compra móvil visible, el aviso sube para no taparla. */
  /* En móvil es una franja bajo el header (no tapa el hero ni el botón de WhatsApp);
     desde sm flota abajo a la derecha y sube si hay barra de compra. */
  @media (width >= 40rem) {
    :global(html.has-sticky-cta) .geo-toast {
      bottom: 10rem;
    }
  }
</style>

sources.src/components/WhatsAppFloat.astro:
---
import { COUNTRIES, DEFAULT_COUNTRY, type Country } from '@/lib/countries';
import { buildWhatsAppUrl } from '@/lib/hotmart';

interface Props {
  country?: Country;
  /** Contexto del mensaje, ej. nombre del curso. */
  context?: string;
}

const { country, context } = Astro.props;
const c = country ?? COUNTRIES.find((x) => x.code === DEFAULT_COUNTRY)!;
const message = context
  ? `Hola 🎈 Me interesa el ${context} y quiero más información.`
  : 'Hola 🎈 Quiero información sobre los cursos de decoración con globos.';
const href = buildWhatsAppUrl(c.whatsapp, message);
---

<a
  href={href}
  target="_blank"
  rel="noopener"
  aria-label={`Escribir por WhatsApp (${c.phoneDisplay})`}
  data-track="click_whatsapp"
  data-track-params={JSON.stringify({ page_location: Astro.url.pathname, course_name: context ?? '' })}
  class="wa-float fixed right-5 bottom-5 z-40 flex h-14 w-14 items-center justify-center rounded-full bg-[#25d366] text-white shadow-globo transition-transform duration-300 ease-fiesta hover:scale-110"
>
  <span class="wa-onda" aria-hidden="true"></span>
  <span class="wa-onda wa-onda-2" aria-hidden="true"></span>
  <svg width="28" height="28" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
    <path
      d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2Zm0 18.2c-1.5 0-3-.4-4.3-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2Zm4.6-6.1c-.3-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1-.2.3-.7.8-.8 1-.1.2-.3.2-.6.1a6.7 6.7 0 0 1-3.3-2.9c-.2-.4.2-.4.6-1.3 0-.2 0-.3-.1-.5l-.8-1.9c-.2-.5-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.3-.2.3-.9.9-.9 2.2s1 2.6 1.1 2.7c.1.2 1.9 2.9 4.6 4.1.6.3 1.1.4 1.5.6.6.2 1.2.2 1.6.1.5-.1 1.5-.6 1.7-1.2.2-.6.2-1.1.2-1.2-.1-.2-.3-.2-.7-.4Z"
    ></path>
  </svg>
</a>

<style>
  /* Con la barra de compra móvil visible, el botón sube para no taparla. */
  .wa-float {
    transition:
      translate 0.4s var(--ease-suave),
      transform 0.3s var(--ease-fiesta);
  }
  :global(html.has-sticky-cta) .wa-float {
    translate: 0 -4.75rem;
  }
  /* Ondas expansivas (patrón LBD Balloons) */
  .wa-onda {
    position: absolute;
    inset: 0;
    border-radius: 9999px;
    background: #25d366;
    opacity: 0.5;
    animation: wa-ondas 1.9s ease-out infinite;
    pointer-events: none;
  }
  .wa-onda-2 {
    animation-delay: 0.6s;
  }
  @keyframes wa-ondas {
    from {
      transform: scale(1);
      opacity: 0.45;
    }
    to {
      transform: scale(2.3);
      opacity: 0;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .wa-onda {
      animation: none;
      opacity: 0;
    }
  }
</style>

sources.src/components/StickyCta.astro:
---
/**
 * Barra de compra fija en móvil. Aparece cuando la caja de compra del hero
 * ([data-buy-box]) sale de pantalla. Se muestra en los 4 cursos (con o sin
 * descuento) y marca <html class="has-sticky-cta"> para que el botón de
 * WhatsApp y el GeoToast suban y no tapen el CTA.
 * Fix 2026-09-22: Tailwind v4 oculta con la propiedad `translate`, no con
 * `transform`; el script anterior nunca la mostraba.
 */
import type { Country } from '@/lib/countries';
import { formatPrice } from '@/lib/countries';
import { usd } from '@/lib/pricing';

interface Props {
  country: Country;
  priceUSD?: number;
  originalPriceUSD?: number;
  discountPct?: number;
  hotmartUrl: string;
  courseName: string;
  coupon: string;
}

const { country, priceUSD, originalPriceUSD, discountPct, hotmartUrl, courseName, coupon } = Astro.props;
const label = discountPct ? `Inscribirme con ${discountPct}% OFF` : 'Inscribirme';
---

<div
  id="sticky-cta"
  class="fixed inset-x-0 bottom-0 z-40 translate-y-full border-t border-crema-200 bg-white/95 pb-[max(0.75rem,env(safe-area-inset-bottom))] backdrop-blur-md transition-[translate] duration-400 ease-suave lg:hidden"
  aria-hidden="true"
>
  <div class="contenedor flex items-center justify-between gap-3 pt-3">
    <div class="min-w-0 leading-tight">
      {
        priceUSD !== undefined ? (
          <>
            {originalPriceUSD !== undefined && (
              <span class="block text-[0.7rem] text-ciruela-500 line-through">{usd(originalPriceUSD)}</span>
            )}
            <span class="block text-lg font-extrabold text-coral-700">{usd(priceUSD)}</span>
            <span class="block text-[0.7rem] font-semibold whitespace-nowrap text-ciruela-500">
              ≈ {formatPrice(priceUSD, country)}
            </span>
          </>
        ) : (
          <span class="block text-xs font-semibold text-ciruela-600">Pago seguro en Hotmart · Garantía 7 días</span>
        )
      }
    </div>
    <a
      href={hotmartUrl}
      target="_blank"
      rel="noopener"
      tabindex="-1"
      data-track="begin_checkout"
      data-track-params={JSON.stringify({
        course_name: courseName,
        price: priceUSD ?? '',
        currency: 'USD',
        discount_code: coupon,
        placement: 'sticky_mobile',
      })}
      class="flex min-h-11 shrink-0 items-center rounded-xl bg-coral-600 px-5 text-sm font-extrabold text-white shadow-boton hover:bg-coral-700"
    >
      {label}
    </a>
  </div>
</div>

<script>
  const bar = document.getElementById('sticky-cta');
  const box = document.querySelector('[data-buy-box]') ?? document.getElementById('curso-hero');
  if (bar && box) {
    const link = bar.querySelector('a');
    const show = (on: boolean) => {
      bar.classList.toggle('translate-y-full', !on);
      bar.classList.toggle('translate-y-0', on);
      bar.setAttribute('aria-hidden', String(!on));
      link?.setAttribute('tabindex', on ? '0' : '-1');
      // Solo en móvil (la barra es lg:hidden): WhatsApp/GeoToast suben para no taparla.
      document.documentElement.classList.toggle('has-sticky-cta', on && matchMedia('(max-width: 63.99rem)').matches);
    };
    new IntersectionObserver(([entry]) => show(!entry.isIntersecting && entry.boundingClientRect.top < 0)).observe(box);
  }
</script>

sources.src/components/FaqAccordion.astro:
---
interface Faq {
  q: string;
  a: string;
}
interface Props {
  faqs: Faq[];
  /** Nombre de curso para el evento view_faq. */
  courseName?: string;
}
const { faqs, courseName = '' } = Astro.props;
---

<div class="faq-list divide-y divide-crema-200 rounded-3xl border border-crema-200 bg-white shadow-tarjeta">
  {
    faqs.map((faq) => (
      <details class="faq-item group px-6" data-question={faq.q} data-course={courseName}>
        <summary class="flex cursor-pointer list-none items-center justify-between gap-4 py-5 text-left font-bold text-ciruela-800 transition-colors hover:text-coral-600 [&::-webkit-details-marker]:hidden">
          <span>{faq.q}</span>
          <span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-crema-100 text-ciruela-600 transition-transform duration-300 ease-fiesta group-open:rotate-45 group-open:bg-coral-100 group-open:text-coral-600">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" />
            </svg>
          </span>
        </summary>
        <div class="pb-5 leading-relaxed text-ciruela-500">{faq.a}</div>
      </details>
    ))
  }
</div>

<style>
  /* Animación nativa de <details> (interpolate-size, progressive enhancement) */
  :global(html) {
    interpolate-size: allow-keywords;
  }
  .faq-item::details-content {
    block-size: 0;
    overflow: hidden;
    transition:
      block-size 0.35s var(--ease-suave),
      content-visibility 0.35s allow-discrete;
  }
  .faq-item[open]::details-content {
    block-size: auto;
  }
</style>

<script>
  import { trackEvent } from '@/lib/analytics';

  document.querySelectorAll<HTMLDetailsElement>('.faq-item').forEach((item) => {
    item.addEventListener('toggle', () => {
      if (item.open) {
        trackEvent('view_faq', {
          faq_question: item.dataset.question ?? '',
          course_name: item.dataset.course ?? '',
        });
      }
    });
  });
</script>

sources.src/components/Icon.astro:
---
/**
 * Icono SVG de trazo propio (ver `src/lib/icons.ts`). Hereda el color con `currentColor`:
 * se colorea con clases de texto (`text-coral-600`, `text-sol-300`…), nunca con emojis.
 * Siempre decorativo (`aria-hidden`): el texto que lo acompaña es el que se lee.
 *
 *   <Icon name="birrete" />                       → 16 px
 *   <Icon name="escudo" size={20} class="text-aqua-700" />
 *   <Icon name="estrella" class="fill-current" />  → relleno
 */
import type { HTMLAttributes } from 'astro/types';
import { ICONS, type IconName } from '@/lib/icons';

type Props = Omit<HTMLAttributes<'svg'>, 'name' | 'width' | 'height'> & {
  name: IconName;
  /** Lado en px (el lienzo es 24×24). */
  size?: number;
  /** Grosor del trazo en unidades del lienzo; 1.8 por defecto (sistema). */
  strokeWidth?: number;
};

const { name, size = 16, strokeWidth = 1.8, class: className, ...rest } = Astro.props;
const paths = ICONS[name];
---

<svg
  xmlns="http://www.w3.org/2000/svg"
  width={size}
  height={size}
  viewBox="0 0 24 24"
  fill="none"
  stroke="currentColor"
  stroke-width={strokeWidth}
  stroke-linecap="round"
  stroke-linejoin="round"
  aria-hidden="true"
  focusable="false"
  class:list={['shrink-0', className]}
  {...rest}
>
  {paths.map((d) => <path d={d} />)}
</svg>

sources.src/components/CourseCard.astro:
---
import type { CollectionEntry } from 'astro:content';
import type { Country } from '@/lib/countries';
import { formatPrice } from '@/lib/countries';
import { getCategory } from '@/lib/categories';
import { coursePricing, usd } from '@/lib/pricing';
import { getCourseRating } from '@/lib/ratings';
import { MIN_VOTES_FOR_SCHEMA } from '@/lib/ratings-config';
import CourseCover from './CourseCover.astro';
import Icon from './Icon.astro';
import Rating from './Rating.astro';

interface Props {
  course: CollectionEntry<'courses'>;
  country?: Country;
  /**
   * Card grande para el grid asimétrico (ocupa 2 filas en lg). En lg la imagen crece para
   * llenar la altura de las 2 filas: la tarjeta necesita `class="h-full"` para estirarse.
   * En tablet (md → lg) ocupa las 2 columnas en horizontal (imagen al 45 %) para no
   * empujar los otros cursos ~600 px hacia abajo.
   */
  large?: boolean;
  /** En lg, imagen a la izquierda (45 %) y texto a la derecha: catálogo a 2 columnas. */
  horizontal?: boolean;
  /** Clases extra para el `<a>` raíz (p. ej. `h-full` para llenar la celda del grid). */
  class?: string;
}

const { course, country, large = false, horizontal = false, class: className } = Astro.props;
const d = course.data;
const category = getCategory(d.category);
// Siempre la URL canónica del curso (las curso-ciudad declaran canonical → curso-país).
const href = `/${country?.code ?? 'co'}/${course.id}/`;
const { hasPrice, hasDiscount, discountPct } = coursePricing(d);
// Estrellas solo con votos reales del sitio (los mismos del aggregateRating de la ficha).
const siteRating = await getCourseRating(course.id);

// La imagen de las variantes `large` (desde md) y `horizontal` (desde lg) deja de tener
// proporción fija: crece con la tarjeta y la foto la cubre en posición absoluta (sin huecos).
const mediaClass = large
  ? 'aspect-square sm:aspect-[16/10] md:aspect-auto md:min-h-64 md:w-[45%] md:shrink-0 lg:min-h-72 lg:w-auto lg:flex-1'
  : horizontal
    ? 'aspect-[16/9] lg:aspect-auto lg:min-h-56 lg:w-[45%] lg:shrink-0'
    : 'aspect-[16/9]';
const imgClass = [
  'h-full w-full object-cover transition-transform duration-700 ease-suave group-hover:scale-105',
  large && 'md:absolute md:inset-0',
  horizontal && !large && 'lg:absolute lg:inset-0',
]
  .filter(Boolean)
  .join(' ');
---

<a
  href={href}
  class:list={[
    'course-card group relative flex flex-col overflow-hidden rounded-3xl border border-crema-200 bg-white shadow-tarjeta',
    horizontal && 'lg:flex-row',
    large && 'md:flex-row lg:flex-col',
    className,
  ]}
>
  <div class:list={['relative overflow-hidden', mediaClass]}>
    {
      d.cover ? (
        <img
          src={d.cover}
          alt={`Imagen del ${d.title}`}
          class={imgClass}
          loading="lazy"
          decoding="async"
          width="600"
          height="600"
        />
      ) : (
        <CourseCover slug={course.id} category={d.category} title={d.title} class={imgClass} />
      )
    }
    <span
      class="absolute top-3 left-3 inline-flex items-center gap-1.5 rounded-full bg-white/90 py-1 pr-3 pl-2.5 text-xs font-extrabold text-ciruela-700 backdrop-blur-sm"
    >
      <Icon name={category.icon} size={14} class="text-coral-600" />
      {category.name}
    </span>
    {
      hasDiscount && discountPct && (
        <span
          class:list={[
            'absolute top-3 right-3 rounded-full bg-coral-600 px-3 py-1 text-xs font-extrabold text-white',
            // En horizontal la imagen mide ~245 px en lg: abajo, para no chocar con el chip de categoría.
            horizontal && 'lg:top-auto lg:bottom-3',
          ]}
        >
          −{discountPct}%
        </span>
      )
    }
  </div>

  <div
    class:list={[
      'flex flex-1 flex-col gap-2.5 p-5',
      large && 'md:justify-center md:p-6 lg:flex-none lg:justify-normal lg:p-5',
      horizontal && 'lg:justify-center lg:p-6',
    ]}
  >
    <h3 class:list={['font-display font-semibold text-ciruela-900', large ? 'text-2xl' : horizontal ? 'text-lg lg:text-xl' : 'text-lg']}>
      {d.title}
    </h3>
    {
      (large || horizontal) && (
        <p class:list={['line-clamp-2 text-sm text-ciruela-500', horizontal && !large && 'max-lg:hidden']}>
          {d.shortDescription}
        </p>
      )
    }
    <div class="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-ciruela-500">
      <span class="inline-flex items-center gap-1">
        <Icon name="play" size={15} class="text-coral-600" />
        {d.lessonsCount} videos
      </span>
      <span>· {d.level}</span>
      <!-- Sin «·» delante: el birrete ya separa y, si la línea se parte (tarjeta horizontal),
           no queda un punto huérfano al inicio. -->
      <span class="inline-flex items-center gap-1">
        <Icon name="birrete" size={15} class="text-coral-600" />
        Certificado
      </span>
      {siteRating.count >= MIN_VOTES_FOR_SCHEMA && <Rating rating={siteRating.average} count={siteRating.count} />}
    </div>
    <div
      class:list={[
        'flex items-baseline gap-2 pt-1.5',
        horizontal ? 'mt-auto lg:mt-2' : large ? 'mt-auto md:mt-2 lg:mt-auto' : 'mt-auto',
      ]}
    >
      {
        hasPrice ? (
          <>
            {hasDiscount && <span class="text-xs text-ciruela-500 line-through">{usd(d.originalPriceUSD!)}</span>}
            <span class="text-lg font-extrabold text-coral-700">{usd(d.priceUSD!)}</span>
            {country && <span class="text-xs text-ciruela-500">≈ {formatPrice(d.priceUSD!, country)}</span>}
          </>
        ) : (
          <span class="inline-flex items-center gap-1 text-sm font-extrabold text-coral-700">
            Ver temario y precio <Icon name="flecha" size={14} />
          </span>
        )
      }
    </div>
  </div>
</a>

<style>
  /* Hover propio del sistema: sube con rebote (ease-fiesta) y gana la sombra `globo`.
     Sin barrido brillante (auditoría 2026-09-22, P1-7: efecto de plantilla). */
  .course-card {
    transition:
      transform 0.4s var(--ease-fiesta),
      box-shadow 0.4s ease;
  }
  .course-card:hover {
    transform: translateY(-8px) scale(1.015);
    box-shadow: var(--shadow-globo);
  }
  .course-card:focus-visible {
    outline: 3px solid var(--color-coral-400);
    outline-offset: 3px;
  }
</style>

sources.src/components/CourseLanding.astro:
---
import { getCollection, render, type CollectionEntry } from 'astro:content';
import BaseLayout from '@/layouts/BaseLayout.astro';
import Wave from '@/components/Wave.astro';
import Balloons from '@/components/Balloons.astro';
import CourseCover from '@/components/CourseCover.astro';
import Rating from '@/components/Rating.astro';
import SectionHeading from '@/components/SectionHeading.astro';
import CourseCard from '@/components/CourseCard.astro';
import TestimonialCard from '@/components/TestimonialCard.astro';
import CertificateShowcase from '@/components/CertificateShowcase.astro';
import FaqAccordion from '@/components/FaqAccordion.astro';
import HotmartBadge from '@/components/HotmartBadge.astro';
import Icon from '@/components/Icon.astro';
import StickyCta from '@/components/StickyCta.astro';
import StarRating from '@/components/StarRating.astro';
import { formatPrice, type Country, type City } from '@/lib/countries';
import { getCategory } from '@/lib/categories';
import { getCityLocal } from '@/lib/cities';
import { buildHotmartUrl } from '@/lib/hotmart';
import { coursePricing, usd } from '@/lib/pricing';
import { postsForCourse, postUrl } from '@/lib/blog';
import { getCourseRating } from '@/lib/ratings';
import { countryAlternates, breadcrumbSchema, courseSchema, faqSchema } from '@/lib/seo';
import { SITE } from '@/lib/site';

interface Props {
  country: Country;
  course: CollectionEntry<'courses'>;
  /** Página hiperlocal: curso a nivel ciudad (§6.2 del plan maestro). */
  city?: City;
}

const { country, course, city } = Astro.props;
const d = course.data;
const { Content } = await render(course);
const category = getCategory(d.category);
const cityLocal = city ? getCityLocal(city.slug) : undefined;
const placeName = city ? city.name : country.name;

const { hasPrice, hasDiscount, discountPct } = coursePricing(d);
const priceDate = d.priceCheckedAt
  ? new Intl.DateTimeFormat('es', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(
      d.priceCheckedAt,
    )
  : undefined;

const checkoutUrl = buildHotmartUrl({
  baseUrl: d.hotmartUrl,
  coupon: d.coupon,
  courseSlug: course.id,
  countryCode: country.code,
  citySlug: city?.slug,
});

const geoFaqs = [
  {
    q: `¿Puedo tomar el ${d.title} desde ${placeName}?`,
    a: `Sí. El curso es 100% online: pagas en Hotmart con métodos disponibles en ${country.name}, recibes el acceso al correo de inmediato y estudias desde el celular o el computador.`,
  },
  {
    q: `¿El certificado es válido en ${country.name}?`,
    a: `Sí. El certificado de estudios es digital, con validez internacional y verificación en línea, útil para tu portafolio y tus clientes en ${placeName}.`,
  },
  {
    q: `¿En qué moneda pago desde ${country.name}?`,
    a: `Hotmart muestra el precio en ${country.currency} (o USD, según el método) antes de confirmar el pago, con el descuento ya aplicado si el curso lo tiene.`,
  },
];
const allFaqs = [...d.faqs, ...geoFaqs, ...(cityLocal?.faqs ?? [])];

// Votos propios del sitio (D1): los mismos números en el widget y en el aggregateRating.
const siteRating = await getCourseRating(course.id);

// Anti-canibalización: la página curso-ciudad declara canonical → curso-país, así que
// el schema y el breadcrumb describen siempre la URL canónica.
const canonicalPath = `/${country.code}/${course.id}/`;
const courseUrl = `${SITE.url}${canonicalPath}`;
const schemas = [
  courseSchema({
    title: d.title,
    description: d.shortDescription,
    url: courseUrl,
    images: d.cover ? [new URL(d.cover, SITE.url).href] : [],
    level: d.level,
    category: category.name,
    learnings: d.learnings,
    price: d.priceUSD,
    producer: d.producer,
    instructor: d.instructor,
    rating: siteRating,
  }),
  faqSchema(allFaqs),
  breadcrumbSchema([
    { name: country.name, url: `${SITE.url}/${country.code}/` },
    { name: 'Cursos', url: `${SITE.url}/${country.code}/cursos/` },
    { name: d.title, url: courseUrl },
  ]),
];

const related = (await getCollection('courses'))
  .filter((c) => c.id !== course.id)
  .sort((a, b) => (a.data.category === d.category ? -1 : 1) - (b.data.category === d.category ? -1 : 1))
  .slice(0, 3);

// Reseñas reales de Hotmart: primero las de este curso, luego las de otros cursos.
const allTestimonials = await getCollection('testimonials');
const testimonials = [
  ...allTestimonials.filter((t) => t.data.courseSlug === course.id),
  ...allTestimonials.filter((t) => t.data.courseSlug !== course.id),
].slice(0, 3);

const guides = await postsForCourse(course.id, 3);

// Title ≤ 60 car. (auditoría 2026-09-22): keyword al inicio + gancho real (descuento o nº de clases).
const offerTag = hasDiscount && discountPct ? `: ${discountPct}% OFF (${usd(d.priceUSD!)})` : ` | ${d.lessonsCount} Clases`;
let metaTitle = d.metaTitle ?? `${d.title} Online en ${placeName}${offerTag}`;
if (!d.metaTitle && metaTitle.length > 60) metaTitle = `${d.title} en ${placeName}${offerTag}`;
const description = (d.metaDescription ?? d.shortDescription).replaceAll('{lugar}', placeName);
const trackBase = {
  course_name: d.title,
  course_category: category.name,
  price: d.priceUSD ?? '',
  currency: d.priceUSD !== undefined ? 'USD' : '',
  country: country.code,
  city: city?.slug ?? '',
  discount_pct: discountPct ?? '',
};
const trackParams = JSON.stringify(trackBase);
/** begin_checkout con la posición del botón (auditoría P2-8: comparar clics por ubicación). */
const ctaTrack = (placement: 'hero' | 'aside_desktop' | 'certificate' | 'closing') =>
  JSON.stringify({ ...trackBase, placement });
const ctaLabel = discountPct ? `Inscribirme con ${discountPct}% OFF` : 'Inscribirme ahora';

// Viñetas de "¿Este curso es para ti?": mini globo (anatomía de Balloons.astro) en colores
// y giros alternos, para que la lista no parezca de plantilla.
const BULLET_TONES = ['text-coral-500', 'text-aqua-500', 'text-sol-500', 'text-lila-500'];
const BULLET_TILT = [-8, 6, -3, 9];

// Sello de garantía: roseta festoneada (22 ondas) generada, no dibujada a ojo.
const SEAL_WAVES = 22;
const sealEdge = (() => {
  const [cx, cy, r, crest] = [60, 58, 44, 50.5];
  const pt = (a: number, rad: number) => `${(cx + rad * Math.cos(a)).toFixed(2)} ${(cy + rad * Math.sin(a)).toFixed(2)}`;
  const step = (Math.PI * 2) / SEAL_WAVES;
  let path = `M${pt(0, r)}`;
  for (let i = 0; i < SEAL_WAVES; i++) path += ` Q${pt((i + 0.5) * step, crest)} ${pt((i + 1) * step, r)}`;
  return `${path}Z`;
})();
---

<BaseLayout
  title={metaTitle}
  {description}
  {country}
  pathAfterCountry={`/${course.id}/`}
  alternates={city ? [] : countryAlternates(`/${course.id}/`)}
  canonicalPath={city ? canonicalPath : undefined}
  {schemas}
  pageType={city ? 'course_city_page' : 'course_page'}
  whatsappContext={d.title}
>
  <!-- view_course (plan de medición §10) -->
  <script
    is:inline
    set:html={`window.dataLayer=window.dataLayer||[];window.dataLayer.push(Object.assign({event:'view_course',page_type:'course_page'},${trackParams}));`}
  />

  <!-- 1-2 · BREADCRUMBS + HERO -->
  <section id="curso-hero" class="relative overflow-hidden bg-crema-100 pt-6 lg:pt-8">
    <Balloons variant="corner-left" />
    <div class="contenedor relative pb-12 lg:pb-16">
      <nav class="mb-4 text-xs text-ciruela-500 lg:mb-8" aria-label="Miga de pan">
        <a href={`/${country.code}/`} class="inline-block py-1 hover:text-coral-600 lg:py-0">{country.flag} {country.name}</a>
        {
          city && (
            <>
              <span aria-hidden="true"> / </span>
              <a href={`/${country.code}/${city.slug}/`} class="inline-block py-1 hover:text-coral-600 lg:py-0">
                {city.name}
              </a>
            </>
          )
        }
        <span aria-hidden="true"> / </span>
        <a href={`/${country.code}/cursos/`} class="inline-block py-1 hover:text-coral-600 lg:py-0">Cursos</a>
        <span aria-hidden="true"> / </span>
        <span class="font-bold text-ciruela-600">{d.title}</span>
      </nav>

      <!-- Mobile: título → imagen → cuadro de compra (patrón de plataforma).
           Desktop: texto+precio a la izquierda, imagen a la derecha. -->
      <div class="grid items-start gap-x-10 gap-y-6 lg:grid-cols-[1.15fr_1fr]">
        <div class="lg:col-start-1">
          <span class="inline-flex items-center gap-1.5 rounded-full bg-white px-3.5 py-1.5 text-xs font-extrabold text-ciruela-700 shadow-tarjeta">
            <Icon name={category.icon} class="text-coral-600" />
            {category.name} · {d.level}
          </span>
          <h1 class="mt-4 text-3xl font-semibold text-balance text-ciruela-900 sm:text-4xl lg:text-[2.75rem]">
            {d.title} en {placeName} — 100% online con certificado
          </h1>
          <p class="mt-4 max-w-xl text-base leading-relaxed text-ciruela-500">{d.shortDescription}</p>

          <StarRating course={course.id} courseTitle={d.title} rating={siteRating} class="mt-4" />

          <div class="mt-3 flex flex-wrap items-center gap-x-2 gap-y-2 text-sm font-semibold text-ciruela-600">
            {
              d.hotmartRating && d.hotmartProductUrl && (
                <a
                  href={d.hotmartProductUrl}
                  target="_blank"
                  rel="noopener nofollow"
                  class="inline-flex items-center gap-1.5 hover:text-coral-600"
                  title="Valoración pública del curso en Hotmart"
                >
                  <Rating rating={d.hotmartRating.value} />
                  <span class="text-xs font-semibold text-ciruela-500">
                    {d.hotmartRating.count} {d.hotmartRating.count === 1 ? 'valoración' : 'valoraciones'} en Hotmart
                  </span>
                </a>
              )
            }
            {d.hotmartRating && <span class="text-coral-400" aria-hidden="true">·</span>}
            <span>{d.lessonsCount} videos</span>
            <span class="text-coral-400" aria-hidden="true">·</span>
            <span>Certificado de estudios</span>
            <span class="text-coral-400" aria-hidden="true">·</span>
            <span>Acceso de por vida</span>
          </div>
        </div>

        <!-- Móvil: 16/10 y sin giro para que la caja de compra suba en el primer viewport (P1-1). -->
        <div class="relative mx-auto w-full max-w-md lg:col-start-2 lg:row-start-1 lg:row-span-2 lg:self-center">
          <div class="overflow-hidden rounded-3xl border-4 border-white shadow-globo sm:rotate-2">
            {
              d.cover ? (
                <img
                  src={d.cover}
                  alt={`Imagen del ${d.title}`}
                  class="aspect-[16/10] w-full object-cover sm:aspect-[4/3]"
                  width="600"
                  height="450"
                  fetchpriority="high"
                />
              ) : (
                <div class="aspect-[16/10] w-full sm:aspect-[4/3]">
                  <CourseCover slug={course.id} category={d.category} title={d.title} />
                </div>
              )
            }
          </div>
          <svg
            class="animate-balloon-float absolute -top-8 -left-6 hidden h-24 w-16 sm:block"
            style="animation-duration: 5.5s"
            viewBox="0 0 40 62"
            fill="none"
            aria-hidden="true"
          >
            <ellipse cx="20" cy="19" rx="17" ry="19" fill="oklch(0.78 0.1 193)"></ellipse>
            <ellipse cx="14" cy="11" rx="5" ry="7" fill="white" opacity="0.32" transform="rotate(-16 14 11)"></ellipse>
            <path d="M20 38 l-2.6 4 h5.2 Z" fill="oklch(0.78 0.1 193)"></path>
            <path d="M20 42.5 q-4 7 0.5 13" stroke="oklch(0.55 0.09 210)" stroke-opacity="0.5" stroke-width="1.3" fill="none" stroke-linecap="round"></path>
          </svg>
        </div>

        <div class="lg:col-start-1">
          <div data-buy-box class="rounded-3xl border border-crema-200 bg-white p-5 shadow-tarjeta sm:p-6">
            {
              hasPrice ? (
                <div class="flex flex-wrap items-center gap-x-4 gap-y-2">
                  <div>
                    {hasDiscount && (
                      <span class="block text-xs text-ciruela-500">
                        Antes <s>{usd(d.originalPriceUSD!)}</s>
                      </span>
                    )}
                    <span class="block font-display text-3xl font-bold text-coral-600">{usd(d.priceUSD!)}</span>
                    <span class="block text-xs text-ciruela-500">
                      ≈ {formatPrice(d.priceUSD!, country)} · Hotmart confirma el valor exacto en {country.currency}
                    </span>
                  </div>
                  {hasDiscount && discountPct && (
                    <span class="rounded-full bg-coral-600 px-4 py-2 text-sm font-extrabold text-white">
                      {discountPct}% OFF aplicado en el enlace
                    </span>
                  )}
                  {priceDate && (
                    <span class="basis-full text-[0.7rem] text-ciruela-400">
                      Precio verificado en el checkout de Hotmart el {priceDate}. Pago único, sin mensualidades.
                    </span>
                  )}
                </div>
              ) : (
                <p class="flex items-start gap-2.5 text-sm font-bold text-ciruela-600">
                  <Icon name="tarjeta" size={20} class="text-coral-600" />
                  <span>
                    El precio se muestra en {country.currency} en el checkout seguro de Hotmart, antes de confirmar
                    el pago.
                  </span>
                </p>
              )
            }
            <div class="mt-5 flex flex-col gap-3 sm:flex-row">
              <a
                href={checkoutUrl}
                target="_blank"
                rel="noopener"
                data-track="begin_checkout"
                data-track-params={ctaTrack('hero')}
                class="rounded-xl bg-coral-600 px-8 py-4 text-center text-sm font-bold text-white shadow-boton transition-all duration-300 ease-fiesta hover:-translate-y-0.5 hover:bg-coral-700"
              >
                {ctaLabel}
              </a>
              <a
