                      name="flecha"
                      size={20}
                      class="hidden text-coral-600 transition-transform duration-300 group-hover:translate-x-1 sm:block"
                    />
                  )}
                </a>
              </li>
            ))}
          </ul>
        </div>
      </section>
    )
  }

  <!-- 13 · FAQ -->
  <section class="contenedor max-w-4xl pb-16">
    <SectionHeading eyebrow="Preguntas frecuentes" title={`Dudas sobre el ${d.title}`} align="center" />
    <div class="mt-8">
      <FaqAccordion faqs={allFaqs} courseName={d.title} />
    </div>
  </section>

  <!-- 14 · RELACIONADOS -->
  <section class="contenedor pb-20">
    <SectionHeading eyebrow="Sigue aprendiendo" title="También te puede interesar" />
    <div class="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
      {related.map((c) => <CourseCard course={c} {country} />)}
    </div>
  </section>

  <StickyCta
    {country}
    priceUSD={d.priceUSD}
    originalPriceUSD={hasDiscount ? d.originalPriceUSD : undefined}
    discountPct={discountPct}
    hotmartUrl={checkoutUrl}
    courseName={d.title}
    coupon={d.coupon ?? (discountPct ? `offDiscount-${discountPct}` : '')}
  />
</BaseLayout>

<style>
  /* Prosa del cuerpo MDX con la voz tipográfica del sitio */
  .prosa :global(p) {
    margin-block: 1rem;
    line-height: 1.75;
    color: var(--color-ciruela-600);
  }
  .prosa :global(h3) {
    margin-top: 2.2rem;
    font-size: 1.35rem;
    font-weight: 600;
    color: var(--color-ciruela-900);
  }
</style>

sources.src/components/StarRating.astro:
---
/**
 * Calificar un curso con estrellas (1-5), estilo kk Star Ratings. El HTML sale del build con
 * los agregados de ese momento —los mismos del `aggregateRating` del JSON-LD— y el script los
 * refresca desde /api/ratings y registra el voto. Sin JS queda de solo lectura. Si hay varias
 * instancias del mismo curso en la página, se mantienen sincronizadas.
 */
import { STAR_LABELS, formatAverage, starFill, votesLabel, type CourseRating } from '@/lib/ratings-config';

interface Props {
  course: string;
  courseTitle: string;
  rating: CourseRating;
  size?: 'md' | 'lg';
  /** Invitación bajo las estrellas; al pasar el cursor se reemplaza por el nombre de la nota. */
  prompt?: string;
  /** Centra estrellas y textos (bloque de la sección de reseñas). */
  center?: boolean;
  class?: string;
}

const {
  course,
  courseTitle,
  rating,
  size = 'md',
  prompt = 'Califícalo: elige de 1 a 5 estrellas',
  center = false,
  class: className,
} = Astro.props;
const STAR = 'M12 2.5l2.9 6 6.6.9-4.8 4.6 1.2 6.5L12 17.4 6.1 20.5l1.2-6.5L2.5 9.4l6.6-.9Z';
---

<div
  class:list={['star-rating flex flex-col gap-1', `star-rating--${size}`, center && 'items-center text-center', className]}
  data-star-rating
  data-course={course}
  data-count={rating.count}
  data-prompt={prompt}
>
  <div class:list={['flex flex-wrap items-center gap-x-2 gap-y-1', center && 'justify-center']}>
    <div class="sr-stars" role="group" aria-label={`Califica el ${courseTitle}`}>
      {
        STAR_LABELS.map((label, i) => (
          <button
            type="button"
            class="sr-star"
            data-value={i + 1}
            style={`--fill:${starFill(rating.average, i + 1)}`}
            aria-label={`${i + 1} de 5 estrellas: ${label}`}
            disabled
          >
            <svg class="sr-empty" viewBox="0 0 24 24" aria-hidden="true">
              <path d={STAR} />
            </svg>
            <span class="sr-full" aria-hidden="true">
              <svg viewBox="0 0 24 24">
                <path d={STAR} />
              </svg>
            </span>
          </button>
        ))
      }
    </div>
    <p class="text-sm text-ciruela-600" data-summary>
      {
        rating.count > 0 ? (
          <>
            <strong class="font-extrabold text-ciruela-900">{formatAverage(rating.average)}</strong> de 5 ·{' '}
            {votesLabel(rating.count)}
          </>
        ) : (
          'Aún sin votos'
        )
      }
    </p>
  </div>
  <p class="min-h-4 text-xs font-bold text-coral-700" data-hint hidden>{prompt}</p>
  <p class="sr-only" data-status aria-live="polite"></p>
</div>

<style>
  .star-rating {
    --star: 1.5rem;
  }
  .star-rating--lg {
    --star: 2.25rem;
  }
  .sr-stars {
    display: inline-flex;
  }
  .sr-star {
    position: relative;
    display: grid;
    place-items: center;
    width: calc(var(--star) + 0.5rem);
    height: calc(var(--star) + 0.5rem);
    border-radius: 0.625rem;
    cursor: pointer;
    transition: transform 0.25s var(--ease-fiesta);
  }
  .sr-star:disabled {
    cursor: default;
  }
  .sr-star svg {
    width: var(--star);
    height: var(--star);
    max-width: none;
  }
  .sr-empty path,
  .sr-full path {
    stroke: oklch(0.62 0.12 70);
    stroke-width: 1;
  }
  .sr-empty path {
    fill: oklch(0.9 0.022 78);
  }
  .sr-full {
    position: absolute;
    top: 0.25rem;
    left: 0.25rem;
    width: calc(var(--fill) * var(--star));
    height: var(--star);
    overflow: hidden;
    transition: width 0.3s ease;
  }
  .sr-full path {
    fill: oklch(0.84 0.145 85);
  }
  /* Vista previa al pasar el cursor o enfocar: se rellenan hasta la estrella señalada. */
  .star-rating[data-preview] .sr-full {
    width: 0;
  }
  .star-rating[data-preview] .is-on .sr-full {
    width: var(--star);
  }
  .star-rating[data-preview] .is-on .sr-full path {
    fill: oklch(0.8 0.16 62);
  }
  .sr-star:not(:disabled):hover {
    transform: translateY(-2px) scale(1.12);
  }
  .sr-star:focus-visible {
    outline: 3px solid var(--color-coral-400);
    outline-offset: 0;
  }
  /* Tu voto: punto coral bajo la estrella elegida. */
  .sr-star[aria-pressed='true']::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 0.3rem;
    height: 0.3rem;
    border-radius: 9999px;
    background: var(--color-coral-600);
    transform: translateX(-50%);
  }
  .star-rating[aria-busy='true'] .sr-star {
    cursor: progress;
    opacity: 0.6;
  }
  @media (prefers-reduced-motion: reduce) {
    .sr-star,
    .sr-full {
      transition: none;
    }
    .sr-star:not(:disabled):hover {
      transform: none;
    }
  }
</style>

<script>
  import { trackEvent } from '@/lib/analytics';
  import {
    STAR_LABELS,
    formatAverage,
    parseCourseRating,
    starFill,
    votesLabel,
    type CourseRating,
  } from '@/lib/ratings-config';

  const API = '/api/ratings';
  const VOTER_KEY = 'cgo:rating-voter';
  const VOTES_KEY = 'cgo:rating-votes';

  // localStorage puede fallar (modo privado, datos bloqueados): votar funciona igual.
  const storage = (() => {
    try {
      const s = window.localStorage;
      s.setItem('cgo:probe', '1');
      s.removeItem('cgo:probe');
      return s;
    } catch {
      return null;
    }
  })();

  let voter: string | undefined;
  /** UUID aleatorio por navegador: un voto por curso, que se puede cambiar. */
  function voterId(): string {
    voter ??= storage?.getItem(VOTER_KEY) ?? undefined;
    if (!voter) {
      voter = crypto.randomUUID();
      storage?.setItem(VOTER_KEY, voter);
    }
    return voter;
  }

  function myVotes(): Record<string, number> {
    try {
      return JSON.parse(storage?.getItem(VOTES_KEY) ?? '{}') as Record<string, number>;
    } catch {
      return {};
    }
  }

  function saveVote(course: string, value: number) {
    try {
      storage?.setItem(VOTES_KEY, JSON.stringify({ ...myVotes(), [course]: value }));
    } catch {
      /* sin almacenamiento: el voto ya quedó en el servidor */
    }
  }

  const widgets = [...document.querySelectorAll<HTMLElement>('[data-star-rating]')];
  /** Cursos votados en esta visita: la respuesta del POST manda sobre el GET de refresco. */
  const votedNow = new Set<string>();
  const forCourse = (course: string) => widgets.filter((w) => w.dataset.course === course);
  const starOf = (target: EventTarget | null) =>
    target instanceof Element ? target.closest<HTMLButtonElement>('.sr-star') : null;

  function setHint(w: HTMLElement, text: string) {
    const hint = w.querySelector<HTMLElement>('[data-hint]');
    if (hint) hint.textContent = text;
  }

  function defaultHint(w: HTMLElement, count: number, mine?: number) {
    if (mine) return `Tu voto: ${mine} ★ · puedes cambiarlo`;
    return count > 0 ? (w.dataset.prompt ?? '') : 'Sé la primera persona en calificarlo';
  }

  function markMine(w: HTMLElement, mine?: number) {
    for (const b of w.querySelectorAll<HTMLButtonElement>('.sr-star')) {
      if (mine) b.setAttribute('aria-pressed', String(Number(b.dataset.value) === mine));
      else b.removeAttribute('aria-pressed');
    }
  }

  function paint(w: HTMLElement, r: CourseRating, mine?: number) {
    w.dataset.count = String(r.count);
    for (const b of w.querySelectorAll<HTMLButtonElement>('.sr-star')) {
      b.style.setProperty('--fill', String(starFill(r.average, Number(b.dataset.value))));
    }
    markMine(w, mine);
    const summary = w.querySelector('[data-summary]');
    if (summary && r.count > 0) {
      const strong = document.createElement('strong');
      strong.className = 'font-extrabold text-ciruela-900';
      strong.textContent = formatAverage(r.average);
      summary.replaceChildren(strong, ` de 5 · ${votesLabel(r.count)}`);
    }
    w.dataset.hintDefault = defaultHint(w, r.count, mine);
    if (w.dataset.preview === undefined) setHint(w, w.dataset.hintDefault);
  }

  function preview(w: HTMLElement, n?: number) {
    if (n) w.dataset.preview = String(n);
    else delete w.dataset.preview;
    for (const b of w.querySelectorAll<HTMLElement>('.sr-star')) {
      b.classList.toggle('is-on', !!n && Number(b.dataset.value) <= n);
    }
    setHint(w, n ? STAR_LABELS[n - 1] : (w.dataset.hintDefault ?? ''));
  }

  function announce(w: HTMLElement, message: string) {
    w.dataset.hintDefault = message;
    setHint(w, message);
    const status = w.querySelector('[data-status]');
    if (status) status.textContent = message;
  }

  async function vote(course: string, value: number) {
    const group = forCourse(course);
    if (group.some((w) => w.getAttribute('aria-busy') === 'true')) return;
    const previous = myVotes()[course];
    group.forEach((w) => w.setAttribute('aria-busy', 'true'));
    let message: string;
    try {
      const res = await fetch(API, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ course, rating: value, voter: voterId() }),
      });
      if (res.status === 429) {
        message = 'Desde tu conexión ya votaron varias personas por este curso.';
      } else {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = parseCourseRating(await res.json());
        if (!data) throw new Error('respuesta inválida');
        saveVote(course, value);
        votedNow.add(course);
        group.forEach((w) => paint(w, data, value));
        message = previous ? `Actualizamos tu voto a ${value} ★. ¡Gracias!` : `¡Gracias! Guardamos tu voto de ${value} ★.`;
        trackEvent('rate_course', { course_slug: course, rating: value, previous_rating: previous ?? 0 });
      }
    } catch {
      message = 'No pudimos guardar tu voto. Intenta de nuevo en un momento.';
    }
    group.forEach((w) => {
      w.removeAttribute('aria-busy');
      announce(w, message);
    });
  }

  const stored = myVotes();
  for (const w of widgets) {
    const course = w.dataset.course ?? '';
    const stars = w.querySelector<HTMLElement>('.sr-stars');
    if (!stars) continue;
    for (const b of stars.querySelectorAll<HTMLButtonElement>('.sr-star')) b.disabled = false;
    markMine(w, stored[course]);
    w.dataset.hintDefault = defaultHint(w, Number(w.dataset.count ?? 0), stored[course]);
    setHint(w, w.dataset.hintDefault);
    w.querySelector<HTMLElement>('[data-hint]')?.removeAttribute('hidden');

    stars.addEventListener('pointerover', (e) => {
      const b = starOf(e.target);
      if (b) preview(w, Number(b.dataset.value));
    });
    stars.addEventListener('pointerleave', () => preview(w));
    stars.addEventListener('focusin', (e) => {
      const b = starOf(e.target);
      if (b) preview(w, Number(b.dataset.value));
    });
    stars.addEventListener('focusout', (e) => {
      if (!stars.contains(e.relatedTarget as Node | null)) preview(w);
    });
    stars.addEventListener('click', (e) => {
      const b = starOf(e.target);
      if (b && !b.disabled) void vote(course, Number(b.dataset.value));
    });
  }

  // Refresco en vivo: el HTML trae los agregados del último build.
  if (widgets.length > 0) {
    fetch(API, { headers: { accept: 'application/json' } })
      .then((r) => (r.ok ? (r.json() as Promise<{ courses?: Record<string, unknown> }>) : null))
      .then((payload) => {
        if (!payload?.courses) return;
        const votes = myVotes();
        for (const w of widgets) {
          const course = w.dataset.course ?? '';
          if (votedNow.has(course)) continue;
          const r = parseCourseRating(payload.courses[course]);
          if (r) paint(w, r, votes[course]);
        }
      })
      .catch(() => {
        /* sin red o sin API: se quedan los datos del build */
      });
  }
</script>

sources.src/components/Balloons.astro:
---
/**
 * Globos decorativos animados (CSS puro, patrón lbdballoons.com):
 *  · animación `floating` (0→25px→0, ~3s ease-in-out) con delays NEGATIVOS
 *    y duraciones ligeramente distintas → desincronización natural.
 *  · globos XL que sangran fuera de la sección (como .globo--v1..v9 de LBD,
 *    que usa imágenes de 536×590 recortadas por el borde).
 *  · parallax sutil al scroll vía wrapper .globo-plx (animation-timeline nativo).
 *
 * variants: "hero" · "rise" · "corner-left" · "corner-right"
 */
interface Props {
  variant?: 'hero' | 'rise' | 'corner-left' | 'corner-right';
}
const { variant = 'hero' } = Astro.props;

interface Globo {
  color: string;
  light: string;
  dark: string;
  size: number;
  left?: string;
  right?: string;
  top?: string;
  bottom?: string;
  delay: string;
  duration: string;
  opacity?: number;
  /** Distancia de parallax al scroll (px, positivo = baja). */
  plx?: number;
  rise?: boolean;
  /** Globo XL sangrante: se oculta en móvil para no tapar el contenido. */
  xl?: boolean;
  /**
   * Dónde se pinta (si falta: en todas partes, salvo los `xl`, que se ven desde 640 px):
   *  · `amplio`   → solo desde 1024 px. En el hero, el H1 ocupa casi todo el ancho hasta lg: los XL
   *                 y los medianos centrados quedaban detrás del titular y de los CTA (en móvil y en
   *                 tablet, «fiestas» en coral sobre el globo amarillo). Auditoría 2026-09-22, P1-4.
   *  · `compacto` → solo por debajo de 1024 px: globos pequeños asomando por las esquinas superiores.
   *                 Lo visible (≤ 20 px) cae dentro del margen lateral del `contenedor`, así que
   *                 nunca cruzan texto ni botones.
   */
  en?: 'amplio' | 'compacto';
}

/** [base, luz, sombra] — la sombra del borde inferior da el volumen del látex real. */
const PALETA = {
  coral: ['oklch(0.62 0.2 14)', 'oklch(0.85 0.09 20)', 'oklch(0.54 0.17 25)'],
  aqua: ['oklch(0.78 0.1 193)', 'oklch(0.92 0.05 194)', 'oklch(0.63 0.1 199)'],
  sol: ['oklch(0.84 0.145 85)', 'oklch(0.95 0.07 89)', 'oklch(0.69 0.13 79)'],
  lila: ['oklch(0.74 0.1 303)', 'oklch(0.9 0.05 304)', 'oklch(0.59 0.11 302)'],
  dorado: ['oklch(0.76 0.12 75)', 'oklch(0.9 0.07 79)', 'oklch(0.61 0.11 72)'],
} as const;

const g = (
  tone: keyof typeof PALETA,
  size: number,
  pos: Partial<Globo>,
  delay: string,
  duration = '3s',
  opacity = 1,
): Globo => ({
  color: PALETA[tone][0],
  light: PALETA[tone][1],
  dark: PALETA[tone][2],
  size,
  delay,
  duration,
  opacity,
  ...pos,
});

const VARIANTS: Record<string, Globo[]> = {
  hero: [
    // XL sangrando fuera de la sección (delays negativos exactos de LBD: 0/-0.3/-0.6/-1)
    { ...g('coral', 320, { left: '-110px', top: '-70px', plx: 110 }, '0s', '3s', 0.95), xl: true, en: 'amplio' },
    { ...g('sol', 250, { right: '-85px', top: '26%', plx: 70 }, '-1s', '3.6s', 0.95), xl: true, en: 'amplio' },
    // Medianos centrados: solo desde lg (antes caían sobre el H1 y los botones).
    { ...g('aqua', 96, { left: '10%', top: '56%', plx: 140 }, '-0.3s', '3.3s', 0.9), en: 'amplio' },
    { ...g('lila', 62, { right: '17%', top: '66%', plx: 90 }, '-0.6s', '3.8s', 0.8), en: 'amplio' },
    { ...g('dorado', 44, { left: '26%', top: '24%', plx: 55 }, '-1.4s', '4.1s', 0.55), en: 'amplio' },
    { ...g('coral', 36, { right: '31%', top: '15%', plx: 40 }, '-2s', '3.5s', 0.5), en: 'amplio' },
    // Móvil y tablet: 2 pequeños asomando por las esquinas superiores (sangran como los XL de LBD).
    { ...g('coral', 32, { left: '-12px', top: '4%', plx: 30 }, '-0.3s', '3.4s', 0.9), en: 'compacto' },
    { ...g('sol', 26, { right: '-8px', top: '4%', plx: 45 }, '-1s', '3.9s', 0.85), en: 'compacto' },
  ],
  'corner-left': [{ ...g('aqua', 230, { left: '-80px', bottom: '-90px', plx: -60 }, '-0.6s', '3.4s', 0.92), xl: true }],
  'corner-right': [{ ...g('lila', 240, { right: '-85px', top: '-80px', plx: 80 }, '-0.3s', '3.2s', 0.92), xl: true }],
  rise: [
    { ...g('coral', 34, { left: '8%' }, '0s', '16s', 0.6), rise: true },
    { ...g('aqua', 26, { left: '28%' }, '4s', '19s', 0.5), rise: true },
    { ...g('sol', 30, { left: '52%' }, '8s', '17s', 0.55), rise: true },
    { ...g('lila', 24, { left: '72%' }, '2s', '20s', 0.45), rise: true },
    { ...g('coral', 28, { left: '88%' }, '6s', '18s', 0.5), rise: true },
  ],
};

const globos = VARIANTS[variant];
let uid = 0;
---

<div class="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden="true">
  {
    globos.map((b) => {
      uid += 1;
      const gradId = `bg-${variant}-${uid}-${b.size}`;
      const pos = `${b.left ? `left:${b.left};` : ''}${b.right ? `right:${b.right};` : ''}${
        b.top ? `top:${b.top};` : b.rise ? 'top:100%;' : ''
      }${b.bottom ? `bottom:${b.bottom};` : ''}`;
      return (
        <div
          class:list={[
            b.rise ? '' : 'globo-plx',
            b.en === 'amplio' ? 'hidden lg:block' : b.xl && 'hidden sm:block',
            b.en === 'compacto' && 'lg:hidden',
          ]}
          style={`position:absolute;${pos}width:${b.size}px;height:${Math.round(b.size * 1.55)}px;${
            b.plx !== undefined ? `--plx:${b.plx}px;` : ''
          }`}
        >
          <svg
            class={b.rise ? 'animate-balloon-rise' : 'animate-floating'}
            style={`width:100%;height:100%;animation-delay:${b.delay};animation-duration:${b.duration};opacity:${b.opacity ?? 1}`}
            viewBox="0 0 40 62"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <defs>
              {/* Volumen de látex real: luz arriba-izq, base, y sombra en el borde (AO) */}
              <radialGradient id={gradId} cx="0.36" cy="0.26" r="0.95">
                <stop offset="0%" stop-color={b.light} />
                <stop offset="52%" stop-color={b.color} />
                <stop offset="100%" stop-color={b.dark} />
              </radialGradient>
              <radialGradient id={`${gradId}-sheen`} cx="0.5" cy="0.5" r="0.5">
                <stop offset="0%" stop-color="white" stop-opacity="0.55" />
                <stop offset="70%" stop-color="white" stop-opacity="0.18" />
                <stop offset="100%" stop-color="white" stop-opacity="0" />
              </radialGradient>
            </defs>
            {/* cuerpo en lágrima (más ancho arriba, afinando hacia el nudo) */}
            <path
              d="M20 1.5 C30.5 1.5 38.5 10 38.5 21 C38.5 30.5 31.5 39.5 23.5 42.7 L20 43.6 L16.5 42.7 C8.5 39.5 1.5 30.5 1.5 21 C1.5 10 9.5 1.5 20 1.5 Z"
              fill={`url(#${gradId})`}
            />
            {/* brillo satinado amplio (patrón del látex real de LBD) */}
            <ellipse
              cx="13.5"
              cy="13"
              rx="7.5"
              ry="11"
              fill={`url(#${gradId}-sheen)`}
              transform="rotate(-20 13.5 13)"
            />
            {/* reflejo secundario sutil al lado derecho */}
            <ellipse cx="30" cy="22" rx="2.6" ry="7" fill="white" opacity="0.12" transform="rotate(14 30 22)" />
            {/* nudo de látex con pestaña */}
            <path d="M20 43 c-2.6 1.6 -3.6 3.2 -3 4.8 h6 c0.6 -1.6 -0.4 -3.2 -3 -4.8 Z" fill={b.dark} />
            <ellipse cx="20" cy="47.6" rx="3.1" ry="1.1" fill={b.dark} opacity="0.85" />
            <path
              d="M20 48.5 q-4 7 0.5 12 q 3.5 4.5 -1 6.5"
              stroke={b.dark}
              stroke-opacity="0.55"
              stroke-width="1.3"
              fill="none"
              stroke-linecap="round"
            />
          </svg>
        </div>
      );
    })
  }
</div>

sources.src/components/CityLanding.astro:
---
import { getCollection } from 'astro:content';
import BaseLayout from '@/layouts/BaseLayout.astro';
import Balloons from '@/components/Balloons.astro';
import Wave from '@/components/Wave.astro';
import SectionHeading from '@/components/SectionHeading.astro';
import CourseCard from '@/components/CourseCard.astro';
import TestimonialCard from '@/components/TestimonialCard.astro';
import FaqAccordion from '@/components/FaqAccordion.astro';
import Icon from '@/components/Icon.astro';
import type { Country, City } from '@/lib/countries';
import { getCityLocal } from '@/lib/cities';
import { breadcrumbSchema, faqSchema } from '@/lib/seo';
import { SITE } from '@/lib/site';

interface Props {
  country: Country;
  city: City;
}

const { country, city } = Astro.props;
const cityLocal = getCityLocal(city.slug);

const courses = (await getCollection('courses')).sort(
  (a, b) => Number(b.data.featured) - Number(a.data.featured),
);
// Reseñas reales de Hotmart (no existen reseñas por ciudad: no se inventan).
const testimonials = (await getCollection('testimonials')).slice(0, 3);

const faqs = [
  ...(cityLocal?.faqs ?? []),
  {
    q: `¿Los cursos son presenciales en ${city.name}?`,
    a: `Son 100% online, y esa es la ventaja: estudias desde cualquier punto de ${city.name} a tu ritmo, sin traslados, y repites cada técnica las veces que quieras antes de un evento real.`,
  },
  {
    q: `¿Cómo pago desde ${country.name}?`,
    a: `En Hotmart, con tarjetas y métodos locales de ${country.name}; el precio se muestra en ${country.currency} antes de confirmar. El acceso llega a tu correo al instante.`,
  },
];

// Intención de la URL: "curso de decoración con globos en {ciudad}". No nombra los 4
// cursos en title/meta para no competir con las money pages por "curso de X".
const title = `Curso de Decoración con Globos en ${city.name}: 100% Online`;
const description = `¿Buscas curso de decoración con globos en ${city.name}? Estudia online, sin traslados: 4 cursos con certificado y pago en ${country.currency}. Garantía de 7 días.`;
---

<BaseLayout
  {title}
  {description}
  {country}
  pathAfterCountry="/"
  schemas={[
    faqSchema(faqs),
    breadcrumbSchema([
      { name: 'Inicio', url: `${SITE.url}/${country.code}/` },
      { name: city.name, url: `${SITE.url}/${country.code}/${city.slug}/` },
    ]),
  ]}
  pageType="city_home"
>
  <section class="relative overflow-hidden bg-crema-100 pt-6 lg:pt-8">
    <Balloons variant="corner-right" />
    <div class="contenedor relative pb-12 lg:pb-16">
      <nav class="mb-4 text-xs text-ciruela-500 lg:mb-8" aria-label="Miga de pan">
        <a href={`/${country.code}/`} class="inline-block py-1 hover:text-coral-600 lg:py-0">{country.flag} {country.name}</a>
        <span aria-hidden="true"> / </span>
        <span class="font-bold text-ciruela-600">{city.name}</span>
      </nav>
      <div class="max-w-3xl">
        <span class="inline-flex items-center gap-1.5 rounded-full bg-white px-3.5 py-1.5 text-xs font-extrabold text-ciruela-700 shadow-tarjeta">
          {country.flag} {city.name}, {country.name}
        </span>
        <h1 class="mt-4 text-3xl font-semibold text-balance text-ciruela-900 sm:text-4xl lg:text-5xl">
          Cursos de decoración con globos en {city.name}
        </h1>
        {cityLocal && <p class="mt-5 max-w-2xl leading-relaxed text-ciruela-600">{cityLocal.hook}</p>}
        <!-- Enlace contextual a la página país (anti-canibalización: la ciudad es una entrada
             local; "curso de decoración con globos online en {país}" vive en /{cc}/). -->
        <p class="mt-3 max-w-2xl text-sm leading-relaxed text-ciruela-600">
          Desde {city.name} tomas el mismo{' '}
          <a
            href={`/${country.code}/`}
            class="font-bold text-coral-700 underline decoration-coral-200 decoration-2 underline-offset-[3px] transition-colors hover:decoration-coral-500"
            >curso de decoración con globos online en {country.name}</a
          >{' '}
          que en cualquier otra ciudad: las mismas especialidades, certificado y pago en {country.currency}.
        </p>
        <div class="mt-7 flex flex-wrap items-center gap-3">
          <a
            href="#cursos-ciudad"
            class="rounded-xl bg-coral-600 px-7 py-3.5 text-sm font-bold text-white shadow-boton transition-all duration-300 ease-fiesta hover:-translate-y-0.5 hover:bg-coral-700"
          >
            Ver los cursos
          </a>
          <ul class="flex flex-wrap items-center gap-x-4 gap-y-1.5 text-xs font-semibold text-ciruela-600">
            <li class="inline-flex items-center gap-1.5">
              <Icon name="birrete" class="text-coral-600" />Certificado incluido
            </li>
            <li class="inline-flex items-center gap-1.5">
              <Icon name="infinito" class="text-coral-600" />Acceso de por vida
            </li>
            <li class="inline-flex items-center gap-1.5">
              <Icon name="escudo" class="text-aqua-700" />Garantía 7 días
            </li>
          </ul>
        </div>
      </div>
    </div>
    <Wave color="var(--color-crema-50)" />
  </section>

  <section id="cursos-ciudad" class="contenedor scroll-mt-24 py-14 lg:py-16">
    <SectionHeading
      eyebrow={`Disponibles en ${city.name}`}
      title="Elige tu especialidad"
      lead={`Los cuatro cursos se estudian 100% online desde ${city.name}, con checkout en ${country.currency} y métodos de pago de ${country.name}.`}
    />
    <div class="mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
      {
        courses.map((course, i) => (
          <div class="scroll-reveal" style={`animation-delay:${i * 60}ms`}>
            <CourseCard {course} {country} class="h-full" />
          </div>
        ))
      }
    </div>
  </section>

  <section class="bg-crema-100 py-14">
    <div class="contenedor">
      <SectionHeading
        eyebrow="Reseñas reales"
        title="Lo que escriben las alumnas en Hotmart"
        lead="Citas textuales de la ficha pública de cada curso en Hotmart, la plataforma donde se compra y se estudia."
      />
      <div class="mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {
          testimonials.map((t, i) => (
            <div class="scroll-reveal" style={`animation-delay:${i * 60}ms`}>
              <TestimonialCard testimonial={t} />
            </div>
          ))
        }
      </div>
    </div>
  </section>

  <section class="contenedor max-w-4xl py-14">
    <SectionHeading
      eyebrow="Preguntas frecuentes"
      title={`Dudas frecuentes desde ${city.name}`}
      align="center"
    />
    <div class="mt-8">
      <FaqAccordion faqs={faqs} />
    </div>
  </section>

  <section class="contenedor pb-16">
    <div class="rounded-[2rem] border border-crema-200 bg-crema-100 p-8">
      <p class="text-xs font-bold tracking-[0.18em] text-ciruela-500 uppercase">
        También estamos en otras ciudades de {country.name}
      </p>
      <div class="mt-3 flex flex-wrap gap-2">
        {
          country.cities
            .filter((c) => c.slug !== city.slug)
            .map((c) => (
              <a
                href={`/${country.code}/${c.slug}/`}
                class="rounded-full border border-crema-300 bg-white px-3.5 py-2.5 text-xs font-bold text-ciruela-600 transition-colors hover:border-coral-300 hover:text-coral-600"
              >
                {c.name}
              </a>
            ))
        }
        <a
          href={`/${country.code}/`}
          class="inline-flex items-center gap-1 rounded-full bg-coral-600 px-3.5 py-2.5 text-xs font-extrabold text-white transition-colors hover:bg-coral-700"
        >
          Todo {country.name} <Icon name="flecha" size={14} />
        </a>
      </div>
    </div>
  </section>
</BaseLayout>

sources.src/components/Seo.astro:
---
import { SITE } from '@/lib/site';
import type { HreflangAlternate } from '@/lib/seo';

export interface ArticleMeta {
  publishedTime: Date;
  modifiedTime: Date;
  author: string;
  section: string;
  tags: string[];
}

interface Props {
  title: string;
  description: string;
  alternates?: HreflangAlternate[];
  schemas?: object[];
  noindex?: boolean;
  ogImage?: string;
  ogImageWidth?: number;
  ogImageHeight?: number;
  ogImageAlt?: string;
  /** og:title distinto del <title> (p. ej. titular pensado para Discover/redes). */
  ogTitle?: string;
  ogType?: 'website' | 'article';
  article?: ArticleMeta;
  /** Canonical distinto de la URL actual (consolidación de duplicados, p. ej. curso-ciudad → curso-país). */
  canonicalPath?: string;
  /** hreflang del país (es-MX → og:locale es_MX). */
  hreflang?: string;
}

const {
  title,
  description,
  alternates = [],
  schemas = [],
  noindex = false,
  ogImage = '/og-default.jpg',
  ogImageWidth,
  ogImageHeight,
  ogImageAlt,
  ogTitle = title,
  ogType = 'website',
  article,
  canonicalPath,
  hreflang = 'es-CO',
} = Astro.props;

const canonical = new URL(canonicalPath ?? Astro.url.pathname, SITE.url).href;
const ogImageUrl = new URL(ogImage, SITE.url).href;
// Google Discover exige permitir vistas previas grandes de imagen (>= 1200px).
// noindex,follow: la página no se indexa pero sus enlaces sí transmiten (catálogo, 404, Ads).
const robots = noindex
  ? 'noindex, follow'
  : 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1';
---

<title>{title}</title>
<meta name="description" content={description} />
{!noindex && <link rel="canonical" href={canonical} />}
<meta name="robots" content={robots} />
{alternates.map((alt) => <link rel="alternate" hreflang={alt.hreflang} href={alt.href} />)}
<link rel="alternate" type="application/rss+xml" title={`Blog de ${SITE.name}`} href={`${SITE.url}/blog/rss.xml`} />

<meta property="og:type" content={ogType} />
<meta property="og:site_name" content={SITE.name} />
<meta property="og:title" content={ogTitle} />
<meta property="og:description" content={description} />
<meta property="og:url" content={canonical} />
<meta property="og:image" content={ogImageUrl} />
{ogImageWidth && <meta property="og:image:width" content={String(ogImageWidth)} />}
{ogImageHeight && <meta property="og:image:height" content={String(ogImageHeight)} />}
{ogImageAlt && <meta property="og:image:alt" content={ogImageAlt} />}
<meta property="og:locale" content={hreflang.replace('-', '_')} />
{
  article && (
    <>
      <meta property="article:published_time" content={article.publishedTime.toISOString()} />
      <meta property="article:modified_time" content={article.modifiedTime.toISOString()} />
      <meta property="article:author" content={article.author} />
      <meta property="article:section" content={article.section} />
      {article.tags.map((tag) => <meta property="article:tag" content={tag} />)}
    </>
  )
}
<meta name="twitter:card" content="summary_large_image" />
<meta name="twitter:title" content={ogTitle} />
<meta name="twitter:description" content={description} />
<meta name="twitter:image" content={ogImageUrl} />
{ogImageAlt && <meta name="twitter:image:alt" content={ogImageAlt} />}

{schemas.map((schema) => <script type="application/ld+json" set:html={JSON.stringify(schema)} />)}

sources.src/components/HotmartBadge.astro:
---
/**
 * Mención factual de la plataforma de pago, junto a los CTA de compra.
 * Términos de uso de Hotmart §5.2: no se puede usar su marca, logotipo o nombre comercial
 * para publicitar un producto ni sugerir que Hotmart lo asocia, aprueba o certifica.
 * Por eso NO se usa su logo ni su color de marca: solo texto neutro que informa dónde
 * se procesa el pago, con un icono propio de candado.
 */
import Icon from './Icon.astro';

interface Props {
  /** dark = para fondos oscuros. */
  tone?: 'light' | 'dark';
  class?: string;
}
const { tone = 'light', class: className } = Astro.props;
---

<span
  class:list={[
    'inline-flex items-center gap-1.5 text-xs font-semibold',
    tone === 'dark' ? 'text-crema-100/80' : 'text-ciruela-600',
    className,
  ]}
>
  <Icon name="candado" size={14} class={tone === 'dark' ? 'text-crema-100/80' : 'text-ciruela-500'} />
  <span>Pago seguro procesado por Hotmart</span>
</span>

sources.src/components/AdsLanding.astro:
---
/**
 * Contenido de landing para Ads (§8.2-8.3). variant "meta": interrupción,
 * copy emocional. variant "google": búsqueda activa, copy directo a datos.
 */
import { getCollection, type CollectionEntry } from 'astro:content';
import Balloons from './Balloons.astro';
import CourseCover from './CourseCover.astro';
import HotmartBadge from './HotmartBadge.astro';
import Icon from './Icon.astro';
import Logo from './Logo.astro';
import Rating from './Rating.astro';
import TestimonialCard from './TestimonialCard.astro';
import Wave from './Wave.astro';
import { COUNTRIES, DEFAULT_COUNTRY, formatPrice } from '@/lib/countries';
import { getCategory } from '@/lib/categories';
import { coursePricing, usd } from '@/lib/pricing';
import { getCourseRating } from '@/lib/ratings';
import { MIN_VOTES_FOR_SCHEMA } from '@/lib/ratings-config';
import { buildHotmartUrl } from '@/lib/hotmart';
import { SITE } from '@/lib/site';

interface Props {
  course: CollectionEntry<'courses'>;
  variant: 'meta' | 'google';
}

const { course, variant } = Astro.props;
const d = course.data;
const country = COUNTRIES.find((c) => c.code === DEFAULT_COUNTRY)!;
const category = getCategory(d.category);
const { hasPrice, hasDiscount, discountPct } = coursePricing(d);
const siteRating = await getCourseRating(course.id);

const checkoutUrl = buildHotmartUrl({
  baseUrl: d.hotmartUrl,
  coupon: d.coupon,
  courseSlug: course.id,
  countryCode: country.code,
  variant: `landing-${variant}`,
});

const isMeta = variant === 'meta';
const h1 = isMeta
  ? `Imagina cobrar por decorar las fiestas de tu ciudad`
  : `${d.title} — ${discountPct ? `${discountPct}% OFF hoy` : 'inscripción abierta'}`;
const sub = isMeta
  ? `El ${d.title} te lleva de cero a tus primeros pedidos: ${d.lessonsCount} videos paso a paso, certificado de estudios y acceso para siempre.`
  : `${d.lessonsCount} videos paso a paso · Certificado de estudios · Acceso de por vida · Garantía de 7 días.`;
// Meta: CTA concreto con la técnica («Quiero aprender globoflexia»), sin emoji como icono.
// Todo en minúscula: los títulos llevan mayúscula a mitad («Bouquets de Globos»).
const skill = d.title.replace(/^Curso de /i, '');
const cta = isMeta
  ? `Quiero aprender ${skill.toLowerCase()}`
  : discountPct
    ? `Inscribirme con ${discountPct}% OFF`
    : 'Inscribirme ahora';

const trackParams = JSON.stringify({
  course_name: d.title,
  course_category: category.name,
  price: d.priceUSD ?? '',
  currency: d.priceUSD !== undefined ? 'USD' : '',
  placement: `landing_${variant}`,
});

const incluye = [
  `${d.lessonsCount} lecciones en video, técnica en cámara`,
  'Certificado de estudios con validez internacional',
  'Acceso de por vida, desde celular o computador',
  'Tareas calificadas y asistencia académica',
  'Bonos prácticos incluidos',
  'Garantía de 7 días — devolución del 100%',
];

// Reseñas REALES de Hotmart (testimonials.json): primero las de este curso y luego las de
// otros cursos (el chip de cada tarjeta dice cuál). Nada de citas inventadas en tráfico pagado.
const allTestimonials = await getCollection('testimonials');
// Relleno alternando cursos (una reseña de cada uno antes de repetir), para que un curso
// sin reseñas propias no muestre tres del mismo curso ajeno.
const seen = new Map<string, number>();
const others = allTestimonials
  .filter((t) => t.data.courseSlug !== course.id)
  .map((t) => {
    const rank = seen.get(t.data.courseSlug) ?? 0;
    seen.set(t.data.courseSlug, rank + 1);
    return { t, rank };
  })
  .sort((a, b) => a.rank - b.rank)
  .map(({ t }) => t);
const testimonials = [...allTestimonials.filter((t) => t.data.courseSlug === course.id), ...others].slice(0, 3);

const faqs = [
  {
    q: '¿Necesito experiencia previa?',
    a: 'No. El curso empieza desde cero y avanza paso a paso hasta las técnicas más vendidas.',
  },
  {
    q: '¿Cómo accedo al curso?',
    a: 'Pagas en Hotmart (métodos locales de tu país) y el acceso llega a tu correo al instante.',
  },
  {
    q: '¿El certificado es válido?',
    a: 'Sí, es un certificado de estudios digital con validez internacional y verificación en línea.',
  },
  {
    q: '¿Y si no me gusta?',
    a: 'Tienes 7 días de garantía: Hotmart te devuelve el 100% de tu dinero, sin preguntas.',
  },
];
---

<!-- Mini header -->
<header class="border-b border-crema-200 bg-crema-50">
  <div class="contenedor flex h-14 items-center justify-between">
    <Logo size={30} />
    {
      discountPct && (
        <span class="rounded-full bg-coral-600 px-4 py-1.5 text-xs font-extrabold text-white">
          {discountPct}% de descuento
        </span>
      )
    }
  </div>
</header>

<main>
  <!-- Hero -->
  <section class="relative overflow-hidden bg-ciruela-900 text-crema-50">
    <Balloons variant="corner-right" />
    <!-- Mobile: título → imagen → precio y CTA. Desktop: texto izq., imagen der. -->
    <div class="contenedor grid items-start gap-x-10 gap-y-6 py-14 lg:grid-cols-[1.1fr_1fr] lg:py-20">
      <div class="lg:col-start-1 lg:self-center">
        <h1 class="text-3xl font-semibold text-balance sm:text-4xl lg:text-5xl">{h1}</h1>
        <p class="mt-4 max-w-lg text-base text-crema-100/85">{sub}</p>
        <div class="mt-4 flex flex-wrap items-center gap-x-4 gap-y-2 text-sm">
          {siteRating.count >= MIN_VOTES_FOR_SCHEMA && (
            <Rating rating={siteRating.average} count={siteRating.count} tone="dark" />
          )}
          <span class="inline-flex items-center gap-1.5 text-crema-100/75">
            <Icon name="birrete" class="text-sol-300" />{SITE.stats.students} estudiantes certificados
          </span>
        </div>
      </div>

      <div class="order-last lg:col-start-1">
        {
          hasPrice && (
            <p>
              {hasDiscount && (
                <span class="text-sm text-crema-100/70">
                  Antes <s>{usd(d.originalPriceUSD!)}</s>
                </span>
              )}
              <span class="font-display mx-3 text-4xl font-bold text-sol-300">{usd(d.priceUSD!)}</span>
              <span class="text-xs text-crema-100/70">≈ {formatPrice(d.priceUSD!, country)}</span>
            </p>
          )
        }
        <a
          href={checkoutUrl}
          target="_blank"
          rel="noopener"
          data-track="begin_checkout"
          data-track-params={trackParams}
          class:list={[
            'inline-block rounded-xl bg-coral-600 px-9 py-4 text-sm font-bold text-white shadow-boton transition-all duration-300 ease-fiesta hover:-translate-y-1 hover:bg-coral-700',
            hasPrice && 'mt-5',
          ]}
        >
          {cta}
        </a>
        <p class="mt-3.5 flex flex-wrap items-center gap-x-4 gap-y-1.5 text-sm font-semibold text-crema-100/80">
          <span class="inline-flex items-center gap-1.5">
            <Icon name="escudo" class="text-sol-300" />Garantía de 7 días · Acceso inmediato
          </span>
          <HotmartBadge tone="dark" />
        </p>
      </div>

      <div class="relative mx-auto w-full max-w-sm lg:col-start-2 lg:row-start-1 lg:row-span-2 lg:self-center">
        <div class="overflow-hidden rounded-3xl border-4 border-crema-50/15 shadow-globo sm:rotate-2">
          {
            d.cover ? (
              <img
                src={d.cover}
                alt={`Imagen del ${d.title}`}
                class="aspect-[16/10] w-full object-cover sm:aspect-[4/3]"
                width="600"
                height="450"
                fetchpriority="high"
              />
            ) : (
              <div class="aspect-[16/10] w-full sm:aspect-[4/3]">
                <CourseCover slug={course.id} category={d.category} title={d.title} />
              </div>
            )
          }
        </div>
      </div>
    </div>
    <Wave color="var(--color-crema-50)" />
  </section>

  <!-- Prueba social rápida: reseñas reales citadas de la ficha pública de Hotmart -->
  <section class="contenedor py-10" aria-labelledby="resenas-titulo">
    <h2 id="resenas-titulo" class="text-xs font-extrabold tracking-[0.18em] text-coral-600 uppercase">
      Reseñas reales de alumnas en Hotmart
    </h2>
    <div class="mt-4 grid gap-5 md:grid-cols-3">
      {testimonials.map((t) => <TestimonialCard testimonial={t} />)}
    </div>
  </section>

  <!-- Qué incluye -->
  <section class="contenedor pb-12">
    <h2 class="font-display text-center text-2xl font-semibold text-ciruela-900 sm:text-3xl">
      {isMeta ? 'Todo lo que te llevas' : 'Qué incluye tu inscripción'}
    </h2>
    <div class="mx-auto mt-8 grid max-w-3xl gap-3 sm:grid-cols-2">
      {
        incluye.map((item) => (
          <div class="flex items-start gap-3 rounded-2xl bg-white p-4 shadow-tarjeta">
            <Icon name="check" size={18} class="mt-px text-coral-600" />
            <span class="text-sm font-semibold text-ciruela-700">{item}</span>
          </div>
        ))
      }
    </div>
  </section>

  <!-- CTA intermedio -->
  <section class="bg-crema-100 py-12">
    <div class="contenedor text-center">
      {
        hasPrice ? (
          <p class="text-sm text-ciruela-500">
            Hoy: {hasDiscount && <s>{usd(d.originalPriceUSD!)}</s>}
            <span class="font-display mx-2 text-3xl font-bold text-coral-700">{usd(d.priceUSD!)}</span>
            {hasDiscount && discountPct && <span class="font-bold text-coral-700">({discountPct}% OFF)</span>}
            <span class="block text-xs">≈ {formatPrice(d.priceUSD!, country)} · Hotmart confirma el valor exacto</span>
          </p>
        ) : (
          <p class="text-sm font-bold text-ciruela-600">Precio en tu moneda, visible antes de pagar.</p>
        )
      }
      <a
        href={checkoutUrl}
        target="_blank"
        rel="noopener"
        data-track="begin_checkout"
        data-track-params={trackParams}
        class="mt-5 inline-block rounded-xl bg-coral-600 px-9 py-4 text-sm font-bold text-white shadow-boton transition-all duration-300 ease-fiesta hover:-translate-y-0.5 hover:bg-coral-700"
      >
        {cta}
      </a>
      <p class="mt-4 text-xs text-ciruela-500">El descuento se aplica automáticamente en el enlace.</p>
    </div>
  </section>

  <!-- Garantía -->
  <section class="contenedor py-12">
    <div class="mx-auto flex max-w-2xl flex-col items-center gap-4 rounded-3xl border-2 border-dashed border-aqua-500 bg-aqua-100/40 p-8 text-center sm:flex-row sm:text-left">
      <span class="flex h-16 w-16 shrink-0 rotate-[-4deg] items-center justify-center rounded-2xl bg-white text-aqua-700 shadow-tarjeta">
        <Icon name="escudo" size={34} strokeWidth={1.6} />
      </span>
      <div>
        <h2 class="font-display text-xl font-semibold text-ciruela-900">7 días de garantía, sin preguntas</h2>
        <p class="mt-1.5 text-sm text-ciruela-600">
          Entra al curso, mira las lecciones y decide. Si no es para ti, Hotmart te devuelve el 100% de tu
          dinero dentro de los primeros 7 días.
        </p>
      </div>
    </div>
  </section>

  <!-- FAQ mínimo -->
  <section class="contenedor max-w-2xl pb-12">
    <h2 class="font-display text-center text-2xl font-semibold text-ciruela-900">Preguntas rápidas</h2>
    <div class="mt-6 divide-y divide-crema-200 rounded-3xl border border-crema-200 bg-white shadow-tarjeta">
      {
        faqs.map((faq) => (
          <details class="group px-6">
            <summary class="flex cursor-pointer list-none items-center justify-between gap-4 py-4 text-sm font-bold text-ciruela-800 [&::-webkit-details-marker]:hidden">
              {faq.q}
              <span class="text-coral-600 transition-transform duration-300 group-open:rotate-45">+</span>
            </summary>
            <p class="pb-4 text-sm text-ciruela-500">{faq.a}</p>
          </details>
        ))
      }
    </div>
  </section>

  <!-- CTA final -->
  <section class="relative overflow-hidden bg-coral-700 py-14 text-center text-white">
    <Balloons variant="rise" />
    <div class="contenedor relative">
      <h2 class="mx-auto max-w-xl text-3xl font-semibold text-balance">
        {isMeta ? 'Tu nueva habilidad te está esperando' : 'Última oportunidad: inscríbete ahora'}
      </h2>
      <p class="mt-3 text-sm text-white/90">Acceso inmediato tras el pago · Certificado incluido</p>
      <a
        href={checkoutUrl}
        target="_blank"
        rel="noopener"
        data-track="begin_checkout"
        data-track-params={trackParams}
        class="mt-6 inline-block rounded-xl bg-white px-10 py-4 text-sm font-bold text-coral-700 shadow-globo transition-all duration-300 ease-fiesta hover:-translate-y-1"
      >
        {cta}
      </a>
    </div>
  </section>
</main>

<!-- Mini footer -->
<footer class="bg-ciruela-900 py-8 text-center text-xs text-crema-100/60">
  <div class="contenedor space-y-2">
    <p>© {new Date().getFullYear()} {SITE.name} · Una filial de Sably</p>
    <p>
      <a href="/legal/terminos/" class="underline hover:text-crema-100">Términos</a> ·
      <a href="/legal/privacidad/" class="underline hover:text-crema-100">Privacidad</a> ·
      <a href={`mailto:${SITE.email}`} class="underline hover:text-crema-100">{SITE.email}</a>
    </p>
  </div>
</footer>

sources.src/components/LeadForm.astro:
---
import type { CollectionEntry } from 'astro:content';
import { COUNTRIES, DEFAULT_COUNTRY, type Country } from '@/lib/countries';

interface Props {
  courses: CollectionEntry<'courses'>[];
  country?: Country;
}

const { courses, country } = Astro.props;
const c = country ?? COUNTRIES.find((x) => x.code === DEFAULT_COUNTRY)!;
---

<form
  id="lead-form"
  data-whatsapp={c.whatsapp}
  class="scroll-reveal relative overflow-hidden rounded-3xl border border-crema-200 bg-white p-6 shadow-globo sm:p-8"
>
  <p class="font-display text-2xl font-semibold text-ciruela-900">¿Tienes dudas antes de empezar?</p>
  <p class="mt-2 text-sm text-ciruela-500">
    Déjanos tus datos y te escribimos por WhatsApp con la información del curso que te interesa. Sin spam, sin
    llamadas raras.
  </p>

  <div class="mt-6 grid gap-4 sm:grid-cols-2">
    <label class="block">
      <span class="mb-1.5 block text-xs font-bold text-ciruela-600">Nombre</span>
      <input type="text" name="nombre" required placeholder="¿Cómo te llamas?" class="field" />
    </label>
    <label class="block">
      <span class="mb-1.5 block text-xs font-bold text-ciruela-600">WhatsApp</span>
      <input type="tel" name="whatsapp" required placeholder={c.phoneDisplay} class="field" />
    </label>
    <label class="block sm:col-span-2">
      <span class="mb-1.5 block text-xs font-bold text-ciruela-600">Curso de interés</span>
      <select name="curso" class="field" required>
        {courses.map((course) => <option value={course.data.title}>{course.data.title}</option>)}
        <option value="Aún no sé">Aún no sé, quiero asesoría</option>
      </select>
    </label>
  </div>

  <button
    type="submit"
    class="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-coral-600 px-6 py-4 text-sm font-bold text-white shadow-boton transition-all duration-300 ease-fiesta hover:-translate-y-0.5 hover:bg-coral-700 sm:w-auto"
  >
    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      <path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2Zm0 18.2c-1.5 0-3-.4-4.3-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2Zm4.6-6.1c-.3-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1-.2.3-.7.8-.8 1-.1.2-.3.2-.6.1a6.7 6.7 0 0 1-3.3-2.9c-.2-.4.2-.4.6-1.3 0-.2 0-.3-.1-.5l-.8-1.9c-.2-.5-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.3-.2.3-.9.9-.9 2.2s1 2.6 1.1 2.7c.1.2 1.9 2.9 4.6 4.1.6.3 1.1.4 1.5.6.6.2 1.2.2 1.6.1.5-.1 1.5-.6 1.7-1.2.2-.6.2-1.1.2-1.2-.1-.2-.3-.2-.7-.4Z"></path>
    </svg>
    Quiero información
  </button>
  <p class="mt-3 text-[0.7rem] text-ciruela-400">
    Al enviar aceptas nuestra <a href="/legal/privacidad/" class="underline">política de privacidad</a>. Tus datos
    solo se usan para responderte.
  </p>
</form>

<script>
  import { trackEvent } from '@/lib/analytics';

  const form = document.getElementById('lead-form') as HTMLFormElement | null;
  form?.addEventListener('submit', (e) => {
    e.preventDefault();
    const data = new FormData(form);
    const nombre = String(data.get('nombre') ?? '');
    const curso = String(data.get('curso') ?? '');
    const tel = String(data.get('whatsapp') ?? '');
    trackEvent('generate_lead', {
      form_name: 'lead_form',
      course_interest: curso,
      country: document.body.dataset.country ?? '',
    });
    const msg = `Hola 🎈 Soy ${nombre}. Me interesa el ${curso} y quiero más información. Mi WhatsApp es ${tel}.`;
    window.open(
      `https://wa.me/${form.dataset.whatsapp}?text=${encodeURIComponent(msg)}`,
      '_blank',
      'noopener',
    );
    form.reset();
  });
</script>

<style>
  .field {
    width: 100%;
    border-radius: 1rem;
    border: 1px solid var(--color-crema-300);
    background: var(--color-crema-50);
    padding: 0.8rem 1rem;
    font-size: 0.95rem;
    color: var(--color-ciruela-800);
    outline: none;
    transition:
      border-color 0.25s ease,
      box-shadow 0.25s ease;
  }
  .field:focus {
    border-color: var(--color-coral-400);
    box-shadow: 0 0 0 3px oklch(0.62 0.2 14 / 0.15);
  }
  /* ciruela-400 sobre crema-50 ≈ 4.6:1 (ciruela-300 daba 3.14:1). */
  .field::placeholder {
    color: var(--color-ciruela-400);
  }
</style>

sources.src/components/CertificateShowcase.astro:
---
/**
 * Muestra del certificado con globo flotante de acento.
 * Hoy la imagen es un mockup fotográfico (papel en blanco con borde y sello dorados, sin texto
 * falso), así que se rotula «Ejemplo ilustrativo» (auditoría P1-10). Cuando exista un
 * certificado real de muestra (nombre de demo o de un alumno que lo autorice), pasar su ruta en
 * `src` con `illustrative={false}`.
 */
import Icon from '@/components/Icon.astro';

interface Props {
  courseName?: string;
  /** Imagen del certificado (por defecto, el mockup en blanco). */
  src?: string;
  /** Rotula la imagen como ejemplo; obligatorio mientras sea un mockup. */
  illustrative?: boolean;
}
const { courseName = 'el curso', src = '/images/certificado-mockup.jpg', illustrative = true } = Astro.props;
const alt = illustrative
  ? `Ejemplo ilustrativo del certificado de estudios que recibes al completar ${courseName}`
  : `Certificado de estudios de muestra de ${courseName}`;
---

<div class="cert-wrap relative mx-auto w-full max-w-md">
  <div class="cert scroll-reveal-late relative rotate-[-2deg] overflow-hidden rounded-2xl border-4 border-white shadow-globo">
    <img
      {src}
      {alt}
      class="block aspect-[4/3] w-full object-cover"
      loading="lazy"
      decoding="async"
      width="1100"
      height="825"
    />
    {
      illustrative && (
        <span class="absolute top-3 right-3 rounded-full bg-ciruela-900/80 px-3 py-1 text-[0.7rem] font-bold tracking-wide text-crema-50 backdrop-blur-sm">
          Ejemplo ilustrativo
        </span>
      )
    }
    <span
      class="absolute bottom-4 left-4 inline-flex items-center gap-1.5 rounded-xl bg-white/92 px-4 py-2 text-xs font-bold text-ciruela-700 backdrop-blur-sm"
    >
      <Icon name="birrete" class="text-coral-600" />
      Certificado de estudios · verificable en línea
    </span>
  </div>
  <!-- globo que asoma detrás del certificado -->
  <svg
    class="animate-floating absolute -top-9 -right-3 -z-10 h-24 w-16 sm:-right-7"
    style="animation-duration: 3.4s; animation-delay: -0.6s"
    viewBox="0 0 40 62"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    aria-hidden="true"
  >
    <ellipse cx="20" cy="19" rx="17" ry="19" fill="oklch(0.84 0.145 85)"></ellipse>
    <ellipse cx="14" cy="11" rx="5" ry="7" fill="white" opacity="0.32" transform="rotate(-16 14 11)"></ellipse>
    <path d="M20 38 l-2.6 4 h5.2 Z" fill="oklch(0.84 0.145 85)"></path>
    <path d="M20 42.5 q-4 7 0.5 13" stroke="oklch(0.62 0.12 70)" stroke-opacity="0.5" stroke-width="1.3" fill="none" stroke-linecap="round"></path>
  </svg>
</div>

<style>
  .cert {
    transition: transform 0.5s var(--ease-fiesta);
  }
  .cert-wrap:hover .cert {
    transform: rotate(-0.3deg) scale(1.02);
  }
</style>

sources.src/components/TestimonialCard.astro:
---
/**
 * Reseña REAL citada de la ficha pública de Hotmart (texto literal, nombre tal como
 * lo publica Hotmart, fecha y enlace a la fuente). No se marca como schema Review:
 * es un dato de terceros (pautas de review snippet de Google).
 */
import { getEntry, type CollectionEntry } from 'astro:content';
import Rating from './Rating.astro';

interface Props {
  testimonial: CollectionEntry<'testimonials'>;
}

const { testimonial } = Astro.props;
const t = testimonial.data;
const course = await getEntry('courses', t.courseSlug);
const AVATAR_COLORS = [
  'oklch(0.55 0.2 15)',
  'oklch(0.55 0.09 210)',
  'oklch(0.52 0.11 302)',
  'oklch(0.58 0.11 70)',
];
const color = AVATAR_COLORS[t.id.charCodeAt(t.id.length - 1) % AVATAR_COLORS.length];
/** Inclinación orgánica determinista (-0.9° / 0° / 0.9°) — se endereza al hover. */
const tilt = ((t.id.charCodeAt(t.id.length - 1) % 3) - 1) * 0.9;
const date = new Intl.DateTimeFormat('es', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(t.date);
---

<figure
  class="flex h-full flex-col gap-4 rounded-3xl border border-crema-200 bg-white p-6 shadow-tarjeta transition-transform duration-300 ease-suave hover:rotate-0"
  style={`rotate: ${tilt}deg`}
>
  <div class="flex items-center justify-between gap-3">
    <Rating rating={t.rating} />
    {
      course && (
        <span class="rounded-full bg-coral-50 px-2.5 py-0.5 text-[0.7rem] font-extrabold text-coral-700">
          {course.data.title.replace('Curso de ', '')}
        </span>
      )
    }
  </div>
  <blockquote class="flex-1 text-sm leading-relaxed text-ciruela-600">“{t.text}”</blockquote>
  <figcaption class="flex items-center gap-3">
    <span
      class="flex h-11 w-11 shrink-0 items-center justify-center rounded-full font-display text-lg font-semibold text-white"
      style={`background:${color}`}
      aria-hidden="true"
    >
      {t.name.charAt(0)}
    </span>
    <span>
      <span class="block text-sm font-extrabold text-ciruela-800">{t.name}</span>
      <span class="block text-xs text-ciruela-500">
        Reseña en{' '}
        <a href={t.sourceUrl} target="_blank" rel="noopener nofollow" class="underline decoration-crema-300 underline-offset-2 hover:text-coral-600">
          Hotmart
        </a>{' '}
        · {date}
      </span>
    </span>
  </figcaption>
</figure>

sources.src/components/CourseCover.astro:
---
/**
 * Portadas ilustradas SVG por curso — dibujadas a mano en la paleta del sitio
 * (nada de fotos con marcas de terceros ni imágenes de stock/IA).
 * Cada curso tiene su escena; fallback: guirnalda orgánica generativa.
 */
interface Props {
  slug: string;
  category: string;
  title: string;
  class?: string;
}
const { slug, category, title, class: className } = Astro.props;

// Paleta compartida
const CORAL = 'oklch(0.62 0.2 14)';
const CORAL_L = 'oklch(0.82 0.09 12)';
const AQUA = 'oklch(0.78 0.1 193)';
const AQUA_D = 'oklch(0.6 0.09 200)';
const SOL = 'oklch(0.84 0.145 85)';
const LILA = 'oklch(0.74 0.1 303)';
const DORADO = 'oklch(0.76 0.12 75)';
const CONFETI = [CORAL, AQUA, SOL, LILA, DORADO];

// Hash determinista para el fallback generativo
let hash = 0;
for (const ch of slug) hash = (hash * 31 + ch.charCodeAt(0)) % 9973;
const rand = (i: number, min: number, max: number) => {
  const x = Math.abs(Math.sin(hash + i * 12.9898) * 43758.5453) % 1;
  return min + x * (max - min);
};
const garland = Array.from({ length: 16 }, (_, i) => {
  const t = i / 15;
  return {
    cx: 30 + t * 340 + rand(i, -14, 14),
    cy: 210 - Math.sin(t * Math.PI) * 150 + rand(i + 40, -12, 12),
    r: rand(i + 80, 11, 27),
    fill: CONFETI[i % CONFETI.length],
  };
}).sort((a, b) => a.r - b.r);

const confetti = (n: number, seed: number) =>
  Array.from({ length: n }, (_, i) => ({
    cx: rand(i + seed, 16, 384),
    cy: rand(i + seed + 100, 14, 210),
    r: rand(i + seed + 200, 1.6, 3.6),
    fill: CONFETI[i % CONFETI.length],
  }));

const scene = ['curso-de-globoflexia', 'curso-de-bouquets-de-globos', 'curso-de-flores-con-globos', 'curso-de-globos-burbuja'].includes(slug)
  ? slug
  : 'garland';
---

<svg
  viewBox="0 0 400 225"
  preserveAspectRatio="xMidYMid slice"
  xmlns="http://www.w3.org/2000/svg"
  role="img"
  aria-label={`Ilustración del ${title}`}
  class:list={['block h-full w-full', className]}
>
  {
    scene === 'curso-de-globoflexia' && (
      <>
        <defs>
          <radialGradient id={`gf-bg-${slug}`} cx="0.3" cy="0.25" r="1.1">
            <stop offset="0%" stop-color="oklch(0.93 0.042 20)" />
            <stop offset="100%" stop-color="oklch(0.82 0.11 20)" />
          </radialGradient>
        </defs>
        <rect width="400" height="225" fill={`url(#gf-bg-${slug})`} />
        {confetti(9, 300).map((c) => (
          <circle cx={c.cx} cy={c.cy} r={c.r} fill={c.fill} opacity="0.5" />
        ))}
        {/* sombra */}
        <ellipse cx="250" cy="200" rx="105" ry="12" fill="oklch(0.44 0.14 25)" opacity="0.18" />
        {/* perrito de globoflexia (capsulas + nudos de torsión) */}
        <g>
          {/* cola */}
          <rect x="176" y="98" width="20" height="46" rx="10" fill={AQUA} transform="rotate(28 186 121)" />
          {/* patas */}
          <rect x="206" y="150" width="21" height="48" rx="10.5" fill={AQUA} />
          <rect x="233" y="150" width="21" height="48" rx="10.5" fill={AQUA} />
          <rect x="277" y="150" width="21" height="48" rx="10.5" fill={AQUA} />
          <rect x="304" y="150" width="21" height="48" rx="10.5" fill={AQUA} />
          {/* cuerpo */}
          <rect x="196" y="116" width="140" height="40" rx="20" fill={AQUA} />
          {/* cuello */}
          <rect x="306" y="76" width="24" height="56" rx="12" fill={AQUA} />
          {/* cabeza / hocico */}
          <rect x="298" y="56" width="66" height="28" rx="14" fill={AQUA} />
          {/* orejas */}
          <rect x="304" y="16" width="19" height="46" rx="9.5" fill={AQUA} />
          <rect x="326" y="16" width="19" height="46" rx="9.5" fill={AQUA} />
          {/* nudos de torsión */}
          <circle cx="216.5" cy="152" r="4.5" fill={AQUA_D} opacity="0.55" />
          <circle cx="243.5" cy="152" r="4.5" fill={AQUA_D} opacity="0.55" />
          <circle cx="287.5" cy="152" r="4.5" fill={AQUA_D} opacity="0.55" />
          <circle cx="314.5" cy="152" r="4.5" fill={AQUA_D} opacity="0.55" />
          <circle cx="318" cy="122" r="5" fill={AQUA_D} opacity="0.55" />
          <circle cx="318" cy="80" r="5" fill={AQUA_D} opacity="0.55" />
          <circle cx="313.5" cy="60" r="4" fill={AQUA_D} opacity="0.55" />
          <circle cx="335.5" cy="60" r="4" fill={AQUA_D} opacity="0.55" />
          <circle cx="194" cy="120" r="4.5" fill={AQUA_D} opacity="0.55" />
          {/* brillos */}
          <ellipse cx="236" cy="126" rx="16" ry="7" fill="white" opacity="0.35" transform="rotate(-12 236 126)" />
          <ellipse cx="316" cy="63" rx="10" ry="4.5" fill="white" opacity="0.4" transform="rotate(-8 316 63)" />
          <ellipse cx="310" cy="26" rx="4" ry="8" fill="white" opacity="0.35" />
          {/* ojo y nariz */}
          <circle cx="342" cy="66" r="3.2" fill="oklch(0.25 0.045 329)" />
          <circle cx="360" cy="70" r="4.5" fill={AQUA_D} />
        </g>
        {/* globo 260 suelto, guiño al material */}
        <rect x="52" y="150" width="90" height="18" rx="9" fill={SOL} transform="rotate(-18 97 159)" />
        <ellipse cx="70" cy="152" rx="9" ry="4" fill="white" opacity="0.4" transform="rotate(-18 70 152)" />
      </>
    )
  }
  {
    scene === 'curso-de-bouquets-de-globos' && (
      <>
        <defs>
          <linearGradient id={`bq-bg-${slug}`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stop-color="oklch(0.94 0.03 305)" />
            <stop offset="100%" stop-color="oklch(0.85 0.07 304)" />
          </linearGradient>
        </defs>
        <rect width="400" height="225" fill={`url(#bq-bg-${slug})`} />
        {confetti(10, 500).map((c) => (
          <circle cx={c.cx} cy={c.cy} r={c.r} fill={c.fill} opacity="0.45" />
        ))}
        {/* cuerdas convergiendo al moño */}
        {[
          [150, 96, 'M150 96 Q168 140 202 172'],
          [205, 62, 'M205 62 Q205 120 203 170'],
          [258, 92, 'M258 92 Q238 140 206 172'],
          [168, 128, 'M168 128 Q184 152 202 172'],
          [244, 130, 'M244 130 Q226 154 206 172'],
        ].map(([, , dPath]) => (
          <path d={dPath as string} stroke="oklch(0.51 0.06 332)" stroke-width="1.6" fill="none" opacity="0.6" />
        ))}
        {/* racimo de globos */}
        <circle cx="150" cy="78" r="30" fill={CORAL} />
        <circle cx="205" cy="52" r="33" fill={SOL} />
        <circle cx="258" cy="76" r="29" fill={AQUA} />
        <circle cx="168" cy="118" r="24" fill={DORADO} />
        <circle cx="244" cy="120" r="25" fill={LILA} />
        <circle cx="205" cy="94" r="36" fill={CORAL_L} />
        {[
          [138, 68, CORAL],
          [193, 42, SOL],
          [248, 66, AQUA],
          [160, 110, DORADO],
          [236, 112, LILA],
          [192, 82, CORAL_L],
        ].map(([cx, cy]) => (
          <ellipse
            cx={cx as number}
            cy={cy as number}
            rx="8"
            ry="11"
            fill="white"
            opacity="0.35"
            transform={`rotate(-18 ${cx} ${cy})`}
          />
        ))}
        {/* moño */}
        <path d="M204 172 l-16 -9 -2 18 Z" fill={DORADO} />
        <path d="M204 172 l16 -9 2 18 Z" fill={DORADO} />
        <circle cx="204" cy="172" r="5" fill="oklch(0.58 0.11 70)" />
        {/* pesita de regalo */}
        <rect x="186" y="180" width="36" height="28" rx="5" fill={CORAL} />
