        <rect x="216" y="118" width="10" height="84" rx="5" fill="oklch(0.62 0.1 165)" />
        <ellipse cx="196" cy="172" rx="22" ry="10" fill="oklch(0.72 0.11 160)" transform="rotate(-32 196 172)" />
        <ellipse cx="248" cy="158" rx="22" ry="10" fill="oklch(0.72 0.11 160)" transform="rotate(28 248 158)" />
        {/* flor principal: 5 pétalos */}
        {[
          [221, 56],
          [180, 86],
          [196, 134],
          [246, 134],
          [262, 86],
        ].map(([cx, cy]) => (
          <circle cx={cx as number} cy={cy as number} r="31" fill={CORAL} />
        ))}
        {[
          [210, 47],
          [169, 78],
          [186, 126],
          [236, 126],
          [252, 78],
        ].map(([cx, cy]) => (
          <ellipse cx={cx as number} cy={cy as number} rx="8" ry="11" fill="white" opacity="0.32" transform={`rotate(-18 ${cx} ${cy})`} />
        ))}
        <circle cx="221" cy="96" r="25" fill={SOL} />
        <circle cx="213" cy="88" r="6" fill="white" opacity="0.45" />
        {/* flor secundaria pequeña */}
        <rect x="94" y="150" width="7" height="56" rx="3.5" fill="oklch(0.62 0.1 165)" />
        {[
          [97, 116],
          [78, 132],
          [86, 155],
          [110, 155],
          [117, 132],
        ].map(([cx, cy]) => (
          <circle cx={cx as number} cy={cy as number} r="14" fill={LILA} />
        ))}
        <circle cx="97" cy="138" r="11" fill={DORADO} />
      </>
    )
  }
  {
    scene === 'curso-de-globos-burbuja' && (
      <>
        <defs>
          <linearGradient id={`bb-bg-${slug}`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stop-color="oklch(0.35 0.055 330)" />
            <stop offset="100%" stop-color="oklch(0.52 0.11 302)" />
          </linearGradient>
        </defs>
        <rect width="400" height="225" fill={`url(#bb-bg-${slug})`} />
        {/* destellos */}
        {[
          [60, 40],
          [340, 30],
          [88, 178],
          [352, 150],
          [140, 24],
        ].map(([cx, cy]) => (
          <path
            d={`M${cx} ${(cy as number) - 6} l1.8 4.2 4.2 1.8 -4.2 1.8 -1.8 4.2 -1.8 -4.2 -4.2 -1.8 4.2 -1.8 Z`}
            fill="white"
            opacity="0.6"
          />
        ))}
        {/* globo burbuja transparente */}
        <circle cx="205" cy="96" r="72" fill="white" opacity="0.1" />
        <circle cx="205" cy="96" r="72" stroke="white" stroke-opacity="0.55" stroke-width="2.5" fill="none" />
        <path d="M158 62 Q172 40 198 34" stroke="white" stroke-opacity="0.6" stroke-width="4" fill="none" stroke-linecap="round" />
        {/* confeti interior (asentado abajo, como el real) */}
        {[
          [178, 138, 6, CORAL],
          [196, 148, 5, SOL],
          [214, 142, 6.5, AQUA],
          [232, 148, 4.5, LILA],
          [186, 152, 4, DORADO],
          [222, 154, 5, CORAL],
          [204, 156, 4.5, AQUA],
          [244, 136, 4, SOL],
          [166, 146, 4.5, LILA],
          [190, 120, 3.5, CORAL],
          [225, 122, 3.5, DORADO],
          [208, 128, 3, SOL],
        ].map(([cx, cy, r, fill]) => (
          <circle cx={cx as number} cy={cy as number} r={r as number} fill={fill as string} opacity="0.95" />
        ))}
        {/* nudo y cola de tassels */}
        <path d="M205 168 l-5 8 h10 Z" fill="white" opacity="0.7" />
        {[
          [205, 184, CORAL],
          [205, 198, SOL],
          [205, 212, AQUA],
        ].map(([cx, cy, fill]) => (
          <path
            d={`M${cx} ${(cy as number) - 7} l7 7 -7 7 -7 -7 Z`}
            fill={fill as string}
            opacity="0.95"
          />
        ))}
        <path d="M205 176 V212" stroke="white" stroke-opacity="0.45" stroke-width="1.6" />
      </>
    )
  }
  {
    scene === 'garland' && (
      <>
        <defs>
          <linearGradient id={`cv-bg-${slug}`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stop-color="oklch(0.985 0.008 84)" />
            <stop offset="100%" stop-color="oklch(0.945 0.02 60)" />
          </linearGradient>
        </defs>
        <rect width="400" height="225" fill={`url(#cv-bg-${slug})`} />
        {confetti(10, 200).map((c) => (
          <circle cx={c.cx} cy={c.cy} r={c.r} fill={c.fill} opacity="0.28" />
        ))}
        {garland.map((b, i) => (
          <g>
            <circle cx={b.cx} cy={b.cy} r={b.r} fill={b.fill} />
            <ellipse
              cx={b.cx - b.r * 0.32}
              cy={b.cy - b.r * 0.38}
              rx={b.r * 0.28}
              ry={b.r * 0.38}
              fill="white"
              opacity={i % 3 === 0 ? 0.4 : 0.28}
              transform={`rotate(-18 ${b.cx - b.r * 0.32} ${b.cy - b.r * 0.38})`}
            />
          </g>
        ))}
      </>
    )
  }
</svg>

sources.src/components/DiscountChip.astro:
---
/**
 * Chip de cupón textual copiable. Este sitio hoy no usa cupones alfanuméricos
 * (el descuento va por offDiscount en el enlace); queda listo para cuando
 * exista un cupón tipo SABLY40 para estos productos.
 */
import Icon from './Icon.astro';

interface Props {
  code: string;
  pct: number;
  courseName?: string;
  class?: string;
}
const { code, pct, courseName = '', class: className } = Astro.props;
---

<button
  type="button"
  class:list={[
    'discount-chip group inline-flex items-center gap-2.5 rounded-full border-2 border-dashed border-coral-400 bg-coral-50 px-4 py-2 transition-colors hover:bg-coral-100',
    className,
  ]}
  data-code={code}
  data-track="copy_discount_code"
  data-track-params={JSON.stringify({ discount_code: code, course_name: courseName })}
  title="Copiar código de descuento"
>
  <span class="inline-flex items-center gap-1.5 text-sm font-bold text-ciruela-700">
    <Icon name="etiqueta" class="text-coral-600" />
    {pct}% OFF con
  </span>
  <code class="font-mono text-sm font-bold tracking-wider text-coral-700">{code}</code>
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" class="chip-icon-copy text-coral-600" aria-hidden="true">
    <rect x="9" y="9" width="11" height="11" rx="2" stroke="currentColor" stroke-width="2"></rect>
    <path d="M5 15V5a2 2 0 0 1 2-2h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
  </svg>
  <Icon name="check" size={15} strokeWidth={2.4} class="chip-icon-ok hidden text-coral-600" />
  <span class="chip-feedback sr-only" role="status"></span>
</button>

<script>
  document.querySelectorAll<HTMLButtonElement>('.discount-chip').forEach((chip) => {
    chip.addEventListener('click', async () => {
      const code = chip.dataset.code ?? '';
      try {
        await navigator.clipboard.writeText(code);
        const feedback = chip.querySelector('.chip-feedback');
        const label = chip.querySelector('code');
        const iconCopy = chip.querySelector('.chip-icon-copy');
        const iconOk = chip.querySelector('.chip-icon-ok');
        if (label && feedback) {
          const original = label.textContent;
          label.textContent = '¡Copiado!';
          iconCopy?.classList.add('hidden');
          iconOk?.classList.remove('hidden');
          feedback.textContent = `Código ${code} copiado`;
          setTimeout(() => {
            label.textContent = original;
            iconCopy?.classList.remove('hidden');
            iconOk?.classList.add('hidden');
          }, 1600);
        }
      } catch {
        /* clipboard no disponible: el código queda visible igualmente */
      }
    });
  });
</script>

