---
import { getCollection } from 'astro:content';
import BaseLayout from '@/layouts/BaseLayout.astro';
import SectionHeading from '@/components/SectionHeading.astro';
import CourseCard from '@/components/CourseCard.astro';
import Icon from '@/components/Icon.astro';
import { COUNTRIES } from '@/lib/countries';
import { CATEGORIES } from '@/lib/categories';
import { countryAlternates, breadcrumbSchema } from '@/lib/seo';
import { SITE } from '@/lib/site';

export function getStaticPaths() {
  return COUNTRIES.map((country) => ({ params: { country: country.code }, props: { country } }));
}

const { country } = Astro.props;
const courses = (await getCollection('courses')).sort(
  (a, b) => Number(b.data.featured) - Number(a.data.featured),
);
const activeCategories = CATEGORIES.filter((cat) => courses.some((c) => c.data.category === cat.slug));
---

<BaseLayout
  title={`Cursos de Globos Online en ${country.name}: Catálogo y Precios`}
  description={`Compara los 4 cursos de globos: globoflexia (50% OFF), bouquets, flores y globos burbuja. Temario, número de clases, precio y certificado de cada uno.`}
  {country}
  pathAfterCountry="/cursos/"
  alternates={countryAlternates('/cursos/')}
  schemas={[
    breadcrumbSchema([
      { name: 'Inicio', url: `${SITE.url}/${country.code}/` },
      { name: 'Cursos', url: `${SITE.url}/${country.code}/cursos/` },
    ]),
  ]}
  pageType="catalog"
>
  <div class="contenedor pt-10 pb-16 lg:pt-12 lg:pb-24">
    <nav class="mb-6 text-xs text-ciruela-500" aria-label="Miga de pan">
      <a href={`/${country.code}/`} class="inline-block py-1 hover:text-coral-600 lg:py-0">{country.flag} {country.name}</a>
      <span aria-hidden="true"> / </span>
      <span class="font-bold text-ciruela-600">Cursos</span>
    </nav>

    <!-- Anti-canibalización: el H1 sigue la intención del <title> (catálogo y precios por país)
         y no repite el de la home ni el de /{cc}/ («Cursos de decoración con globos…»). -->
    <SectionHeading as="h1"
      eyebrow="Catálogo completo"
      title={`Catálogo de cursos de globos en ${country.name}: precios y temarios`}
      lead={`Técnicas paso a paso con certificado de estudios y acceso permanente. Los precios se muestran en ${country.currency} y el pago es seguro con Hotmart.`}
    />

    <div class="mt-8 flex flex-wrap gap-2">
      <span class="rounded-full bg-coral-600 px-4 py-2 text-xs font-extrabold text-white">Todos</span>
      {
        activeCategories.map((cat) => (
          <a
            href={`/${country.code}/cursos/${cat.slug}/`}
            class="inline-flex items-center gap-1.5 rounded-full border border-crema-300 bg-white py-2 pr-4 pl-3 text-xs font-bold text-ciruela-600 transition-colors hover:border-coral-300 hover:text-coral-600"
          >
            <Icon name={cat.icon} size={15} class="text-coral-600" />
            {cat.name}
          </a>
        ))
      }
    </div>

    <!-- 2 columnas con tarjetas horizontales en lg: con 4 cursos, a 3 columnas quedaba una huérfana. -->
    <div id="catalogo" class="mt-10 grid gap-6 sm:grid-cols-2">
      {
        courses.map((course, i) => (
          <div class="scroll-reveal curso-item" data-title={course.data.title.toLowerCase()} style={`animation-delay:${i * 60}ms`}>
            <CourseCard {course} {country} horizontal class="h-full" />
          </div>
        ))
      }
    </div>
    <p id="sin-resultados" class="mt-10 hidden items-center justify-center gap-2 text-center text-sm text-ciruela-500">
      <Icon name="globo" class="text-coral-600" />
      No encontramos cursos con ese nombre. Escríbenos por WhatsApp y te ayudamos a elegir.
    </p>
  </div>

  <script>
    // Filtro simple ?q= desde el buscador del menú mobile
    const q = new URLSearchParams(location.search).get('q')?.toLowerCase().trim();
    if (q) {
      const items = document.querySelectorAll<HTMLElement>('.curso-item');
      let visible = 0;
      items.forEach((item) => {
        const match = (item.dataset.title ?? '').includes(q);
        item.style.display = match ? '' : 'none';
        if (match) visible++;
      });
      if (visible === 0) document.getElementById('sin-resultados')?.classList.replace('hidden', 'flex');
    }
  </script>
</BaseLayout>

sources.src/pages/[country]/[item]/index.astro:
---
/**
 * Ruta dual /{cc}/{item}/ — `item` puede ser un slug de curso
 * (/co/curso-de-globoflexia/) o una ciudad (/co/bogota/). Patrón [item] del
 * ecosistema Sably para evitar colisión de rutas dinámicas al mismo nivel.
 */
import { getCollection, type CollectionEntry } from 'astro:content';
import CourseLanding from '@/components/CourseLanding.astro';
import CityLanding from '@/components/CityLanding.astro';
import { COUNTRIES, CITIES_ENABLED, type Country, type City } from '@/lib/countries';

export async function getStaticPaths() {
  const courses = await getCollection('courses');
  return COUNTRIES.flatMap((country) => [
    ...courses.map((course) => ({
      params: { country: country.code, item: course.id },
      props: { country, course, city: undefined },
    })),
    ...(CITIES_ENABLED
      ? country.cities.map((city) => ({
          params: { country: country.code, item: city.slug },
          props: { country, course: undefined, city },
        }))
      : []),
  ]);
}

interface Props {
  country: Country;
  course?: CollectionEntry<'courses'>;
  city?: City;
}

const { country, course, city } = Astro.props;
---

{course ? <CourseLanding {country} {course} /> : <CityLanding {country} city={city!} />}

sources.src/pages/[country]/[item]/[curso]/index:
---
/**
 * Curso hiperlocal: /{cc}/{ciudad}/{curso-slug}/ (§6.2 del plan maestro).
 * Recupera las URLs geo del sitio anterior (/bogota/curso-de-globoflexia/ →
 * /co/bogota/curso-de-globoflexia/) con contenido local único por ciudad.
 */
import { getCollection } from 'astro:content';
import CourseLanding from '@/components/CourseLanding.astro';
import { COUNTRIES, CITIES_ENABLED } from '@/lib/countries';

export async function getStaticPaths() {
  if (!CITIES_ENABLED) return [];
  const courses = await getCollection('courses');
  return COUNTRIES.flatMap((country) =>
    country.cities.flatMap((city) =>
      courses.map((course) => ({
        params: { country: country.code, item: city.slug, curso: course.id },
        props: { country, city, course },
      })),
    ),
  );
}

const { country, city, course } = Astro.props;
---

<CourseLanding {country} {city} {course} />

sources.src/pages/[country]/cursos/[category]/in:
---
import { getCollection } from 'astro:content';
import BaseLayout from '@/layouts/BaseLayout.astro';
import SectionHeading from '@/components/SectionHeading.astro';
import CourseCard from '@/components/CourseCard.astro';
import { COUNTRIES } from '@/lib/countries';
import { CATEGORIES } from '@/lib/categories';
import { countryAlternates, breadcrumbSchema } from '@/lib/seo';
import { SITE } from '@/lib/site';

export async function getStaticPaths() {
  const courses = await getCollection('courses');
  const activeCategories = CATEGORIES.filter((cat) => courses.some((c) => c.data.category === cat.slug));
  return COUNTRIES.flatMap((country) =>
    activeCategories.map((category) => ({
      params: { country: country.code, category: category.slug },
      props: { country, category },
    })),
  );
}

const { country, category } = Astro.props;
// Con una sola categoría activa, esta página duplica el catálogo /{cc}/cursos/ y competía
// con él y con /{cc}/ (auditoría 2026-09-22): noindex,follow hasta tener ≥ 2 categorías.
const allCourses = await getCollection('courses');
const activeCount = new Set(allCourses.map((c) => c.data.category)).size;
const courses = (await getCollection('courses'))
  .filter((c) => c.data.category === category.slug)
  .sort((a, b) => Number(b.data.featured) - Number(a.data.featured));
---

<BaseLayout
  title={`Cursos de ${category.name} en ${country.name} 🎈 Online`}
  description={`${category.short} Cursos online con certificado para ${country.name}.`}
  {country}
  pathAfterCountry={`/cursos/${category.slug}/`}
  noindex={activeCount < 2}
  alternates={countryAlternates(`/cursos/${category.slug}/`)}
  schemas={[
    breadcrumbSchema([
      { name: 'Inicio', url: `${SITE.url}/${country.code}/` },
      { name: 'Cursos', url: `${SITE.url}/${country.code}/cursos/` },
      { name: category.name, url: `${SITE.url}/${country.code}/cursos/${category.slug}/` },
    ]),
  ]}
  pageType="category"
>
  <div class="contenedor pt-10 pb-16 lg:pt-12 lg:pb-24">
    <nav class="mb-6 text-xs text-ciruela-500" aria-label="Miga de pan">
      <a href={`/${country.code}/`} class="hover:text-coral-600">{country.flag} {country.name}</a>
      <span aria-hidden="true"> / </span>
      <a href={`/${country.code}/cursos/`} class="hover:text-coral-600">Cursos</a>
      <span aria-hidden="true"> / </span>
      <span class="font-bold text-ciruela-600">{category.name}</span>
    </nav>

    <SectionHeading as="h1"
      eyebrow="Categoría"
      title={`Cursos de ${category.name.toLowerCase()}`}
      lead={category.short}
    />

    <div class="mt-8 flex flex-wrap gap-2">
      {
        category.subcategories.map((sub) => (
          <span class="rounded-full border border-crema-300 bg-white px-3.5 py-1.5 text-xs font-bold text-ciruela-500">
            {sub.name}
          </span>
        ))
      }
    </div>

    <!-- Igual que el catálogo: 2 columnas con tarjetas horizontales en lg (sin tarjeta huérfana). -->
    <div class="mt-10 grid gap-6 sm:grid-cols-2">
      {
        courses.map((course, i) => (
          <div class="scroll-reveal" style={`animation-delay:${i * 60}ms`}>
            <CourseCard {course} {country} horizontal class="h-full" />
          </div>
        ))
      }
    </div>

    <div class="mt-12 rounded-3xl border border-crema-200 bg-crema-100 p-8 text-center">
      <p class="font-display text-xl font-semibold text-ciruela-900">¿No sabes por cuál empezar?</p>
      <p class="mx-auto mt-2 max-w-md text-sm text-ciruela-500">
        Cuéntanos qué quieres lograr y te recomendamos el curso ideal según tu experiencia y tu presupuesto.
      </p>
      <a
        href={`/${country.code}/`}
        class="mt-5 inline-block rounded-xl bg-coral-600 px-6 py-3 text-xs font-bold text-white transition-colors hover:bg-coral-700"
      >
        Pedir asesoría gratis
      </a>
    </div>
  </div>
</BaseLayout>

sources.src/pages/blog/[slug]/index.astro:
---
import { getImage, Picture } from 'astro:assets';
import { render } from 'astro:content';
import BaseLayout from '@/layouts/BaseLayout.astro';
import FaqAccordion from '@/components/FaqAccordion.astro';
import CourseCta from '@/components/blog/CourseCta.astro';
import Callout from '@/components/blog/Callout.astro';
import Toc from '@/components/blog/Toc.astro';
import AuthorBox from '@/components/blog/AuthorBox.astro';
import PostCard from '@/components/blog/PostCard.astro';
import { getPublishedPosts, relatedPosts, readingMinutes, formatDate, lastModified, type Post } from '@/lib/blog';
import { getBlogCluster } from '@/lib/blog-clusters';
import { getAuthor } from '@/lib/authors';
import { blogPostingSchema, breadcrumbSchema, faqSchema } from '@/lib/seo';
import { SITE } from '@/lib/site';

export async function getStaticPaths() {
  const posts = await getPublishedPosts();
  return posts.map((post) => ({ params: { slug: post.id }, props: { post, all: posts } }));
}

interface Props {
  post: Post;
  all: Post[];
}

const { post, all } = Astro.props;
const d = post.data;
const { Content, headings } = await render(post);
const cluster = getBlogCluster(d.cluster);
const author = getAuthor(d.author);
const url = `${SITE.url}/blog/${post.id}/`;
const modified = lastModified(post);
const minutes = readingMinutes(post);
const pillar = d.pillar ? all.find((p) => p.id === d.pillar) : undefined;
const related = relatedPosts(post, all, 3);

// Discover/Article: imagen >= 1200px en 16:9, 4:3 y 1:1 (Google elige la que mejor encaja).
const [og169, og43, og11] = await Promise.all([
  getImage({ src: d.hero, width: 1600, height: 900, fit: 'cover', format: 'jpg', quality: 82 }),
  getImage({ src: d.hero, width: 1200, height: 900, fit: 'cover', format: 'jpg', quality: 80 }),
  getImage({ src: d.hero, width: 1200, height: 1200, fit: 'cover', format: 'jpg', quality: 80 }),
]);
const abs = (src: string) => new URL(src, SITE.url).href;

const wordCount = (post.body ?? '').split(/\s+/).filter(Boolean).length;
const schemas = [
  blogPostingSchema({
    url,
    headline: d.title,
    description: d.description,
    images: [abs(og169.src), abs(og43.src), abs(og11.src)],
    datePublished: d.publishedAt,
    dateModified: modified,
    author,
    section: cluster.name,
    keywords: d.keywords,
    wordCount,
  }),
  breadcrumbSchema([
    { name: 'Inicio', url: `${SITE.url}/` },
    { name: 'Blog', url: `${SITE.url}/blog/` },
    { name: d.title, url },
  ]),
  ...(d.faqs.length > 0 ? [faqSchema(d.faqs)] : []),
];

const trackParams = JSON.stringify({
  post_slug: post.id,
  post_cluster: d.cluster,
  money_page: d.moneyPage,
  is_pillar: d.isPillar,
});
---

<BaseLayout
  title={d.seoTitle ?? d.title}
  description={d.description}
  {schemas}
  pageType="blog_post"
  whatsappContext={d.title}
  ogTitle={d.discoverTitle ?? d.title}
  ogType="article"
  ogImage={og169.src}
  ogImageWidth={1600}
  ogImageHeight={900}
  ogImageAlt={d.heroAlt}
  article={{
    publishedTime: d.publishedAt,
    modifiedTime: modified,
    author: author.name,
    section: cluster.name,
    tags: d.keywords.slice(0, 6),
  }}
>
  <script
    is:inline
    set:html={`window.dataLayer=window.dataLayer||[];window.dataLayer.push(Object.assign({event:'view_blog_post',page_type:'blog_post'},${trackParams}));`}
  />

  <div class="contenedor pt-6 pb-20 lg:pt-10">
    <nav aria-label="Migas de pan" class="text-xs text-ciruela-400">
      <ol class="flex flex-wrap items-center gap-1.5">
        <li><a href="/" class="hover:text-coral-600">Inicio</a></li>
        <li aria-hidden="true">/</li>
        <li><a href="/blog/" class="hover:text-coral-600">Blog</a></li>
        <li aria-hidden="true">/</li>
        <li><a href={`/blog/#${cluster.slug}`} class="hover:text-coral-600">{cluster.name}</a></li>
      </ol>
    </nav>

    <header class="mt-5 max-w-3xl">
      <p class="text-xs font-extrabold tracking-[0.2em] text-coral-600 uppercase">
        {d.isPillar ? `Guía completa · ${cluster.name}` : cluster.name}
      </p>
      <h1 class="mt-3 text-[2.1rem] leading-[1.08] font-semibold text-ciruela-900 sm:text-5xl">{d.title}</h1>
      <p class="mt-4 text-lg leading-relaxed text-ciruela-500">{d.description}</p>
      <div class="mt-5 flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-ciruela-500">
        <a href={`/blog/autor/${author.slug}/`} rel="author" class="font-bold text-ciruela-700 hover:text-coral-600">
          {author.name}
        </a>
        <span aria-hidden="true">·</span>
        {
          d.updatedAt ? (
            <span>
              Actualizado el <time datetime={modified.toISOString()}>{formatDate(modified)}</time>
            </span>
          ) : (
            <span>
              <time datetime={d.publishedAt.toISOString()}>{formatDate(d.publishedAt)}</time>
            </span>
          )
        }
        <span aria-hidden="true">·</span>
        <span>{minutes} min de lectura</span>
      </div>
    </header>

    <figure class="mt-8 overflow-hidden rounded-3xl bg-crema-200 shadow-tarjeta">
      <Picture
        src={d.hero}
        alt={d.heroAlt}
        widths={[480, 800, 1200, 1600]}
        sizes="(min-width: 1184px) 1120px, calc(100vw - 2.5rem)"
        formats={['avif', 'webp']}
        loading="eager"
        fetchpriority="high"
        class="aspect-[16/9] w-full object-cover"
      />
    </figure>

    <div class="mt-10 grid gap-12 lg:grid-cols-[minmax(0,1fr)_17rem] xl:gap-16">
      <div class="min-w-0">
        <div class="mb-8 lg:hidden">
          <Toc {headings} collapsible />
        </div>

        <div class="articulo">
          <Content components={{ CourseCta, Callout }} />
        </div>

        {
          d.faqs.length > 0 && (
            <section class="mt-14" aria-labelledby="faq-titulo">
              <h2 id="faq-titulo" class="mb-6 text-2xl font-semibold text-ciruela-900 sm:text-3xl">
                Preguntas frecuentes
              </h2>
              <FaqAccordion faqs={d.faqs} />
            </section>
          )
        }

        <CourseCta curso={d.moneyPage} />

        {
          pillar && (
            <p class="mb-8 rounded-2xl border border-crema-200 bg-white px-5 py-4 text-sm text-ciruela-600">
              Esta guía es parte de{' '}
              <a href={`/blog/${pillar.id}/`} class="font-bold text-coral-600 underline-offset-2 hover:underline">
                {pillar.data.title}
              </a>
              , nuestra guía completa sobre {cluster.name.toLowerCase()}.
            </p>
          )
        }

        <AuthorBox {author} />
      </div>

      <aside class="hidden lg:block" aria-label="Navegación del artículo">
        <div class="sticky top-28 space-y-8">
          <Toc {headings} />
          <CourseCta curso={d.moneyPage} variante="compacta" texto={d.moneyAnchor} />
        </div>
      </aside>
    </div>

    {
      related.length > 0 && (
        <section class="mt-20" aria-labelledby="relacionados-titulo">
          <h2 id="relacionados-titulo" class="text-2xl font-semibold text-ciruela-900 sm:text-3xl">
            Sigue leyendo
          </h2>
          <div class="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {related.map((p) => (
              <PostCard post={p} />
            ))}
          </div>
        </section>
      )
    }
  </div>
</BaseLayout>

<script>
  // Resalta en el TOC la sección visible (sin librerías).
  const links = new Map(
    [...document.querySelectorAll<HTMLAnchorElement>('[data-toc-link]')].map((a) => [a.dataset.tocLink!, a]),
  );
  if (links.size > 0 && 'IntersectionObserver' in window) {
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          links.forEach((a) => a.removeAttribute('aria-current'));
          links.get(entry.target.id)?.setAttribute('aria-current', 'true');
        }
      },
      { rootMargin: '-20% 0px -70% 0px' },
    );
    document.querySelectorAll('.articulo h2[id]').forEach((h) => io.observe(h));
  }
</script>

sources.src/pages/blog/autor/[slug]/index.astro:
---
import BaseLayout from '@/layouts/BaseLayout.astro';
import PostCard from '@/components/blog/PostCard.astro';
import { AUTHORS, authorUrl, type Author } from '@/lib/authors';
import { getPublishedPosts } from '@/lib/blog';
import { breadcrumbSchema, ORG_ID } from '@/lib/seo';
import { SITE } from '@/lib/site';

export function getStaticPaths() {
  return Object.values(AUTHORS).map((author) => ({ params: { slug: author.slug }, props: { author } }));
}

interface Props {
  author: Author;
}
const { author } = Astro.props;
const posts = (await getPublishedPosts()).filter((p) => p.data.author === author.slug);
const url = authorUrl(author.slug);

const schemas = [
  {
    '@context': 'https://schema.org',
    '@type': 'ProfilePage',
    url,
    inLanguage: 'es',
    mainEntity: {
      '@type': author.type,
      name: author.name,
      url,
      description: author.bio,
      ...(author.type === 'Organization' ? { parentOrganization: { '@id': ORG_ID } } : {}),
      ...(author.jobTitle ? { jobTitle: author.jobTitle } : {}),
      ...(author.sameAs ? { sameAs: author.sameAs } : {}),
    },
  },
  breadcrumbSchema([
    { name: 'Inicio', url: `${SITE.url}/` },
    { name: 'Blog', url: `${SITE.url}/blog/` },
    { name: author.name, url },
  ]),
];
---

<BaseLayout
  title={author.type === 'Organization' ? `Equipo editorial | ${SITE.name}` : `${author.name} | ${SITE.name}`}
  description={author.bio.slice(0, 155)}
  pageType="author"
  {schemas}
>
  <div class="contenedor pt-10 pb-20 lg:pt-14">
    <header class="max-w-3xl">
      <p class="text-xs font-extrabold tracking-[0.22em] text-coral-600 uppercase">Autor</p>
      <h1 class="mt-3 text-4xl font-semibold text-ciruela-900 sm:text-5xl">{author.name}</h1>
      <p class="mt-4 text-lg leading-relaxed text-ciruela-500">{author.bio}</p>
      <p class="mt-4 text-sm text-ciruela-500">
        Cómo trabajamos: cada guía cita medidas y costos de referencia, se revisa contra el temario de los cursos y
        se actualiza cuando cambian técnicas, materiales o precios. ¿Ves algo que corregir? Escríbenos a
        <a href={`mailto:${SITE.email}`} class="font-bold text-coral-600">{SITE.email}</a>.
      </p>
    </header>

    <h2 class="mt-14 text-2xl font-semibold text-ciruela-900">Guías publicadas ({posts.length})</h2>
    <div class="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
      {posts.map((p) => <PostCard post={p} />)}
    </div>
  </div>
</BaseLayout>

