sources.src/components/blog/Callout.astro:
---
/**
 * Nota destacada en MDX (sin import): `<Callout tipo="consejo" titulo="Truco de taller">…</Callout>`.
 * Tipos: consejo (aqua), ojo (frambuesa, errores comunes), dato (sol, cifras y medidas).
 */
interface Props {
  tipo?: 'consejo' | 'ojo' | 'dato';
  titulo?: string;
}
const { tipo = 'consejo', titulo } = Astro.props;
// Etiqueta siempre en tinta (contraste AA a 12px); el color del tipo vive en el borde.
const styles = {
  consejo: { box: 'border-aqua-500 bg-aqua-100/60', label: 'text-ciruela-800', name: 'Consejo' },
  ojo: { box: 'border-coral-400 bg-coral-50', label: 'text-ciruela-800', name: 'Ojo' },
  dato: { box: 'border-sol-500 bg-sol-100/70', label: 'text-ciruela-800', name: 'Dato útil' },
}[tipo];
---

<aside class:list={['callout not-prose my-7 rounded-2xl border-l-4 px-5 py-4', styles.box]}>
  <p class:list={['mb-1 text-xs font-extrabold tracking-[0.16em] uppercase', styles.label]}>
    {titulo ?? styles.name}
  </p>
  <div class="text-[0.97rem] leading-relaxed text-ciruela-700 [&_p+p]:mt-2 [&_strong]:text-ciruela-900">
    <slot />
  </div>
</aside>

sources.src/components/blog/CourseCta.astro:
---
/**
 * Caja de conversión dentro de un artículo (disponible en MDX sin import:
 * `<CourseCta curso="curso-de-globoflexia" />`). Enlaza a la money page del
 * curso — nunca directo a Hotmart — para no saltarse la página que convierte
 * y medir el paso blog → curso (evento click_blog_cta).
 */
import { getEntry } from 'astro:content';
import { coursePricing, usd } from '@/lib/pricing';

interface Props {
  curso: string;
  /** Frase propia del artículo; si falta se usa la descripción del curso. */
  texto?: string;
  variante?: 'normal' | 'compacta';
}

const { curso, texto, variante = 'normal' } = Astro.props;
const isCatalog = curso === 'catalogo';
const course = isCatalog ? undefined : await getEntry('courses', curso);
if (!isCatalog && !course) throw new Error(`CourseCta: curso desconocido "${curso}"`);

const d = course?.data;
const href = isCatalog ? '/co/cursos/' : `/co/${curso}/`;
const title = d?.title ?? 'Cursos online de decoración con globos';
const body =
  texto ??
  d?.shortDescription ??
  'Globoflexia, bouquets, flores y globos burbuja: cuatro cursos con certificado, a tu ritmo y con acceso de por vida.';
const pricing = d ? coursePricing(d) : undefined;
const hasPrice = pricing?.hasPrice ?? false;
const hasDiscount = pricing?.hasDiscount ?? false;
const trackParams = JSON.stringify({ course_slug: curso, placement: variante });
---

{
  variante === 'compacta' ? (
    <aside class="not-prose my-8 flex flex-col gap-3 rounded-2xl border border-coral-100 bg-coral-50 p-5 sm:flex-row sm:items-center sm:justify-between">
      <p class="text-[0.95rem] leading-snug text-ciruela-700">
        <strong class="text-ciruela-900">{title}:</strong> {body}
      </p>
      <a
        href={href}
        data-track="click_blog_cta"
        data-track-params={trackParams}
        class="shrink-0 rounded-xl bg-coral-600 px-5 py-2.5 text-sm font-bold text-white transition-colors hover:bg-coral-700"
      >
        Ver el curso
      </a>
    </aside>
  ) : (
    <aside class="not-prose my-10 overflow-hidden rounded-3xl border border-crema-200 bg-white shadow-tarjeta sm:flex">
      {d?.cover && (
        <img
          src={d.cover}
          alt={`Portada del ${d.title}`}
          width="600"
          height="600"
          loading="lazy"
          decoding="async"
          class="aspect-[16/9] w-full object-cover sm:aspect-auto sm:w-56"
        />
      )}
      <div class="flex flex-1 flex-col gap-3 p-6">
        <p class="text-[0.7rem] font-extrabold tracking-[0.18em] text-coral-600 uppercase">
          {isCatalog ? 'Aprende con método' : 'Curso online con certificado'}
        </p>
        <p class="font-display text-xl font-semibold text-ciruela-900">{title}</p>
        <p class="text-sm leading-relaxed text-ciruela-500">{body}</p>
        <div class="mt-1 flex flex-wrap items-center gap-x-4 gap-y-2">
          <a
            href={href}
            data-track="click_blog_cta"
            data-track-params={trackParams}
            class="rounded-xl bg-coral-600 px-5 py-3 text-sm font-bold text-white shadow-boton transition-colors hover:bg-coral-700"
          >
            {isCatalog ? 'Ver los cursos' : hasPrice ? `Ver el curso · ${usd(d!.priceUSD!)}` : 'Ver temario y precio'}
          </a>
          <span class="text-xs text-ciruela-500">
            {hasDiscount && (
              <>
                Antes <s>{usd(d!.originalPriceUSD!)}</s> ·{' '}
              </>
            )}
            Acceso de por vida · Garantía de 7 días en Hotmart
          </span>
        </div>
      </div>
    </aside>
  )
}

sources.src/components/blog/Toc.astro:
---
import type { MarkdownHeading } from 'astro';

interface Props {
  headings: MarkdownHeading[];
  /** En móvil se muestra plegable. */
  collapsible?: boolean;
}
const { headings, collapsible = false } = Astro.props;
const items = headings.filter((h) => h.depth === 2);
---

{
  items.length >= 3 &&
    (collapsible ? (
      <details class="toc rounded-2xl border border-crema-200 bg-white px-5 py-4 shadow-tarjeta">
        <summary class="cursor-pointer list-none text-sm font-extrabold text-ciruela-800 [&::-webkit-details-marker]:hidden">
          En esta guía ({items.length} secciones)
        </summary>
        <ol class="mt-3 space-y-2 border-t border-crema-200 pt-3 text-sm">
          {items.map((h) => (
            <li>
              <a href={`#${h.slug}`} class="text-ciruela-600 hover:text-coral-600">
                {h.text}
              </a>
            </li>
          ))}
        </ol>
      </details>
    ) : (
      <nav aria-label="Contenido del artículo" class="toc">
        <p class="mb-3 text-[0.7rem] font-extrabold tracking-[0.18em] text-ciruela-400 uppercase">En esta guía</p>
        <ol class="space-y-2 border-l-2 border-crema-200 text-sm">
          {items.map((h) => (
            <li>
              <a
                href={`#${h.slug}`}
                data-toc-link={h.slug}
                class="-ml-0.5 block border-l-2 border-transparent pl-3.5 leading-snug text-ciruela-500 transition-colors hover:text-coral-600 aria-[current=true]:border-coral-500 aria-[current=true]:font-bold aria-[current=true]:text-ciruela-900"
              >
                {h.text}
              </a>
            </li>
          ))}
        </ol>
      </nav>
    ))
}

sources.src/components/blog/PostCard.astro:
---
import { Picture } from 'astro:assets';
import type { Post } from '@/lib/blog';
import { formatDate, lastModified, postUrl, readingMinutes } from '@/lib/blog';
import { getBlogCluster } from '@/lib/blog-clusters';

interface Props {
  post: Post;
  /** Tarjeta horizontal grande (destacado del índice). */
  featured?: boolean;
  /** La imagen de la primera tarjeta visible puede ser el LCP. */
  eager?: boolean;
  headingLevel?: 'h2' | 'h3';
}

const { post, featured = false, eager = false, headingLevel = 'h3' } = Astro.props;
const d = post.data;
const cluster = getBlogCluster(d.cluster);
const Heading = headingLevel;
---

<article
  class:list={[
    'post-card group relative flex overflow-hidden rounded-3xl border border-crema-200 bg-white shadow-tarjeta',
    featured ? 'flex-col md:flex-row' : 'flex-col',
  ]}
>
  <div class:list={['relative overflow-hidden', featured ? 'aspect-[16/9] md:aspect-auto md:w-[56%]' : 'aspect-[16/9]']}>
    <Picture
      src={d.hero}
      alt={d.heroAlt}
      widths={featured ? [480, 768, 1100] : [400, 640, 800]}
      sizes={featured ? '(min-width: 768px) 640px, 100vw' : '(min-width: 1024px) 380px, (min-width: 640px) 50vw, 100vw'}
      formats={['avif', 'webp']}
      loading={eager ? 'eager' : 'lazy'}
      fetchpriority={eager ? 'high' : 'auto'}
      class="h-full w-full object-cover transition-transform duration-700 ease-suave group-hover:scale-[1.04]"
    />
    {
      d.isPillar && (
        <span class="absolute top-3 left-3 rounded-full bg-ciruela-900/85 px-3 py-1 text-[0.7rem] font-extrabold tracking-wide text-white backdrop-blur-sm">
          Guía completa
        </span>
      )
    }
  </div>
  <div class:list={['flex flex-1 flex-col gap-2.5', featured ? 'p-6 md:p-8 md:justify-center' : 'p-5']}>
    <p class="text-[0.7rem] font-extrabold tracking-[0.18em] text-coral-600 uppercase">{cluster.name}</p>
    <Heading class:list={['font-display font-semibold text-ciruela-900', featured ? 'text-2xl md:text-3xl' : 'text-lg']}>
      <a href={postUrl(post)} class="after:absolute after:inset-0 focus-visible:outline-none">
        {d.title}
      </a>
    </Heading>
    <p class:list={['text-sm leading-relaxed text-ciruela-500', featured ? 'line-clamp-3' : 'line-clamp-2']}>
      {d.description}
    </p>
    <p class="mt-auto pt-1 text-xs text-ciruela-400">
      <time datetime={lastModified(post).toISOString()}>{formatDate(lastModified(post))}</time>
      · {readingMinutes(post)} min de lectura
    </p>
  </div>
</article>

<style>
  .post-card {
    transition:
      transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),
      box-shadow 0.4s ease;
  }
  .post-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-globo);
  }
  .post-card:has(a:focus-visible) {
    outline: 3px solid var(--color-coral-400);
    outline-offset: 3px;
  }
</style>
